local config = {
  ui_story_5066_50660101_1_dialog_content = "Escadas, armários, pisos...",
  ui_story_5066_50660101_2_dialog_content = "Ufa... Finalmente todos estão limpos.",
  ui_story_5066_50660101_3_dialog_content = "Isso significa que eu deveria ter terminado a limpeza de hoje... Certo?",
  ui_story_5066_50660101_4_dialog_content = "Connolly! Onde você foi? O chão está todo limpo?",
  ui_story_5066_50660101_5_dialog_content = "Ah! É minha tia!",
  ui_story_5066_50660101_6_dialog_content = "E-eu estou no porão! Acabei de terminar aqui embaixo!",
  ui_story_5066_50660101_7_dialog_content = "Sério? Porque eu acabei de ver algumas manchas no corredor de novo!",
  ui_story_5066_50660101_8_dialog_content = "Temos convidados importantes chegando nos próximos dias, e toda a família está ocupada. Não atrapalhe!",
  ui_story_5066_50660101_9_dialog_content = "Tá... Já tô indo aí!",
  ui_story_5066_50660101_10_dialog_content = "Este deve ser o lugar...",
  ui_story_5066_50660101_11_dialog_content = "Ah! Essa área toda está coberta de areia dos sapatos das pessoas...",
  ui_story_5066_50660101_12_dialog_content = "Preciso limpar isso imediatamente e ir direto para o sótão...",
  ui_story_5066_50660101_13_dialog_content = "Caso contrário... Minha tia vai gostar ainda menos de mim se ela ver isso.",
  ui_story_5066_50660101_14_dialog_content = "Ei, Connolly!",
  ui_story_5066_50660101_15_dialog_content = "Ei—É você, primo?",
  ui_story_5066_50660101_16_dialog_content = "M-Mas eu pensei que você tinha sido promovido a uma posição alta lá no Raso...",
  ui_story_5066_50660101_17_dialog_content = "Haha, é surpreendente que você ainda se lembre de tudo isso. Eu sou realmente um membro valioso do Tribunal dos Tritões agora.",
  ui_story_5066_50660101_18_dialog_content = "Você também vai limpar a sala hoje? Que dona de casa, pequena Connolly!",
  ui_story_5066_50660101_19_dialog_content = "Terminarei em breve... Não vou desperdiçar mais tempo de todos!",
  ui_story_5066_50660101_20_dialog_content = "Você não vai participar do banquete da família?",
  ui_story_5066_50660101_21_dialog_content = "Eu... eu nunca poderia participar...",
  ui_story_5066_50660101_22_dialog_content = "Durante banquetes... Minha tia ou me tranca no sótão ou me obriga a sair de casa...",
  ui_story_5066_50660101_23_dialog_content = "Ela não quer assustar nossos convidados, já que eu pareço tão estranha...",
  ui_story_5066_50660101_24_dialog_content = "Que pena. Sua aparência é realmente bastante peculiar para um morador desta cidade subaquática.",
  ui_story_5066_50660101_25_dialog_content = "Ainda assim, aos meus olhos, essa peculiaridade é uma forma de estética.",
  ui_story_5066_50660101_26_dialog_content = "Posso te apresentar a um emprego melhor, onde você não ficará sozinho mais.",
  ui_story_5066_50660101_27_dialog_content = "D-Desculpe, mas eu deveria ir agora! Minha tia ainda tem muitas coisas para eu fazer!",
  ui_story_5066_50660101_28_dialog_content = "Ei, espera!",
  ui_story_5066_50660101_29_dialog_content = "... Ingratas!",
  ui_story_5066_50660101_30_dialog_content = "Ah, graças a Deus consegui escapar...",
  ui_story_5066_50660101_31_dialog_content = "Ele parece realmente interessado em mim, mas sua atitude vulgar realmente me deixa desconfortável...",
  ui_story_5066_50660101_32_dialog_content = "Mesmo que eu pudesse sair... Não seria com ele...",
  ui_story_5066_50660101_33_dialog_content = "Sei que me sentiria solitário se saísse sozinho... Mas realmente não me importo de ficar sozinho.",
  ui_story_5066_50660101_34_dialog_content = "Sinceramente, estar em um lugar sem outras pessoas me convém perfeitamente.",
  ui_story_5066_50660101_35_dialog_content = "<color=#e8d9bb>Connolly acredita que se ninguém notá-la, então ninguém pode odiá-la, evitá-la ou apontar dedos para ela.</color>",
  ui_story_5066_50660101_36_dialog_content = "Quem é essa? A aparência dela é realmente estranha - não se parece com um peixe de jeito nenhum. Ela é da cidade?",
  ui_story_5066_50660101_37_dialog_content = "O nome dela é Connolly, ouvi dizer. E ela é adotada.",
  ui_story_5066_50660101_38_dialog_content = "Sem ideia de que tipo de peixe eram os pais dela para ter uma filha tão estranha.",
  ui_story_5066_50660101_39_dialog_content = "Sou o único que parece diferente nesta casa...",
  ui_story_5066_50660101_40_dialog_content = "Mamãe e papai se foram agora... Apenas minha tia estava disposta a me acolher...",
  ui_story_5066_50660101_41_dialog_content = "Mas não importa o quanto eu tente fazer parte desta família... Simplesmente não há lugar para mim aqui.",
  ui_story_5066_50660101_42_dialog_content = "Ainda assim, eu não estou completamente infeliz...",
  ui_story_5066_50660101_43_dialog_content = "E isso é porque... Eu ainda tenho minha música! Ainda tenho o instrumento e as partituras que minha mãe me deixou...",
  ui_story_5066_50660101_44_dialog_content = "<color=#e8d9bb>Quando Connolly se sente solitária, ela toca aquelas melodias familiares.</color>",
  ui_story_5066_50660101_45_dialog_content = "<color=#e8d9bb>Uma marcha alegre em Lá Maior, uma balada lírica em Si Menor e uma sonata sombria em Dó Maior. Essas músicas não são apenas suas amigas, mas sua salvação.</color>",
  ui_story_5066_50660101_46_dialog_content = "Agora, qual música devo tocar hoje...?",
  ui_story_5066_50660101_47_dialog_content = "Huh...? Essa pontuação...",
  ui_story_5066_50660101_48_dialog_content = "O-O-O que essa música assustadora ainda está fazendo aqui?!",
  ui_story_5066_50660101_49_dialog_content = "A última vez que joguei, algo extremamente terrível aconteceu!",
  ui_story_5066_50660101_50_dialog_content = "Até convocou um monstro de tentáculos, um que se chamava...",
  ui_story_5066_50660101_51_dialog_content = "Eu sou o <color=#FFB400>Senhor das Águas</color>...",
  ui_story_5066_50660101_52_dialog_content = "O selado... antigo... Senhor Aqua!",
  ui_story_5066_50660101_53_dialog_content = "A filha comum da água que segura a relíquia sagrada, você consegue compreender minhas palavras?",
  ui_story_5066_50660101_54_dialog_content = "...?",
  ui_story_5066_50660101_55_dialog_content = "Aaaaaaaah! É-é um monstro!",
  ui_story_5066_50660101_56_dialog_content = "Por favor, não me coma!!!",
  ui_story_5066_50660101_57_dialog_content = "... Eu nunca consumo seres mortais!",
  ui_story_5066_50660101_58_dialog_content = "Estou aqui porque seu clarinete não é uma coisa comum...",
  ui_story_5066_50660101_59_dialog_content = "Sua música me trouxe até aqui.",
  ui_story_5066_50660101_60_dialog_content = "Desejo fazer um pacto com você.",
  ui_story_5066_50660101_61_dialog_content = "Um... pacto?",
  ui_story_5066_50660101_62_dialog_content = "Sim, o poderoso Aqua Pact! Com o Pact, você pode ser a rainha e governar todo o mundo submarino!",
  ui_story_5066_50660101_63_dialog_content = "A rainha... do mundo submarino...",
  ui_story_5066_50660101_64_dialog_content = "Então, tudo o que você precisa fazer é tocar a relíquia sagrada que simboliza nosso pacto... este próprio clarinete!",
  ui_story_5066_50660101_65_dialog_content = "Meu poder se manifestará, ajudando você a conquistar todos os mares!",
  ui_story_5066_50660101_66_dialog_content = "Você não precisará mais temer nada no mundo!",
  ui_story_5066_50660101_67_dialog_content = "Agora, me diga, qual é a sua resposta?",
  ui_story_5066_50660101_68_dialog_content = "... May Posso recusar, por favor?",
  ui_story_5066_50660101_69_dialog_content = "?",
  ui_story_5066_50660101_70_dialog_content = "Ah! Uh, s-sabe... Sobre me tornar rainha e essas coisas...",
  ui_story_5066_50660101_71_dialog_content = "Eu não acho que consigo fazer algo que pareça tão difícil ou notável...",
  ui_story_5066_50660101_72_dialog_content = "M-Meu maior desejo é que as pessoas parem de me notar...",
  ui_story_5066_50660101_73_dialog_content = "Eu não quero nenhum problema. Só quero ouvir minha música...",
  ui_story_5066_50660101_74_dialog_content = "<size=33>Se eu tivesse apenas um ou dois amigos, ou talvez até três para ouvir música comigo... Isso seria suficiente...</size>",
  ui_story_5066_50660101_75_dialog_content = "...",
  ui_story_5066_50660101_76_dialog_content = "Entendi. Você não está pronto para assumir a responsabilidade do reino subaquático.",
  ui_story_5066_50660101_77_dialog_content = "Mas esta partitura é prova do nosso possível pacto.",
  ui_story_5066_50660101_78_dialog_content = "Para me chamar, toque isso com seu clarinete.",
  ui_story_5066_50660101_79_dialog_content = "Apenas toque... toque... toque...",
  ui_story_5066_50660101_80_dialog_content = "Achei que era apenas o precioso instrumento que mamãe deixou para mim...",
  ui_story_5066_50660101_81_dialog_content = "Por que ele pode invocar uma criatura tão misteriosa...?",
  ui_story_5066_50660101_82_dialog_content = "Não vai ficar comigo para sempre... Vai?",
  ui_story_5066_50660101_83_dialog_content = "Toque...",
  ui_story_5066_50660101_84_dialog_content = "O pacto...",
  ui_story_5066_50660101_85_dialog_content = "Para me chamar...",
  ui_story_5066_50660101_86_dialog_content = "Ahhhhh... Só de pensar nisso, já consigo ouvir a voz de novo!",
  ui_story_5066_50660101_87_dialog_content = "Eu só preciso... me concentrar em outra coisa...",
  ui_story_5066_50660101_88_dialog_content = "<color=#e8d9bb>Bata, bate, bate—</color>",
  ui_story_5066_50660101_89_dialog_content = "Hã? Quem poderia estar me procurando no sótão a essa hora...?",
  ui_story_5066_50660101_90_dialog_content = "Connolly! Estamos ficando sem ingredientes na cozinha novamente! Corra e vá comprar mais!",
  ui_story_5066_50660101_91_dialog_content = "Ah... Ok! Vou sair agora mesmo!",
  ui_story_5066_50660201_1_dialog_content = "Ufa... Isso deve evitar que minha tia fique muito brava.",
  ui_story_5066_50660201_2_dialog_content = "Ainda assim, o que está acontecendo hoje...?",
  ui_story_5066_50660201_3_dialog_content = "Já está na hora? Por que eles ainda não chegaram?",
  ui_story_5066_50660201_4_dialog_content = "Com licença, perdoe-me...",
  ui_story_5066_50660201_5_dialog_content = "Boo-hoo... Por que as ruas estão tão cheias hoje?",
  ui_story_5066_50660201_6_dialog_content = "Parece que todo mundo saiu para ver algo... Hoje é algum feriado especial...?",
  ui_story_5066_50660201_7_dialog_content = "O que você disse?",
  ui_story_5066_50660201_8_dialog_content = "Você quer dizer que não sabe? Hoje é o dia de passeio do <color=#FFB400>príncipe</color>! Todos estão nas ruas, tentando dar uma olhada no príncipe!",
  ui_story_5066_50660201_9_dialog_content = "Huh, eu gostaria de ver o rosto do cara que nos taxa o tempo todo!",
  ui_story_5066_50660201_10_dialog_content = "... Eu não esperava encontrar isso hoje. Multidões assim me assustam demais.",
  ui_story_5066_50660201_11_dialog_content = "Preciso voltar correndo assim que terminar de comprar os suprimentos...",
  ui_story_5066_50660201_12_dialog_content = "É o príncipe! O príncipe está aqui!",
  ui_story_5066_50660201_13_dialog_content = "Ha!",
  ui_story_5066_50660201_14_dialog_content = "Ugh, isso é tão chato, muito, muito chato!",
  ui_story_5066_50660201_15_dialog_content = "Que cidade horrível. Eu deveria ficar dentro de casa e nunca sair. Por que meu pai me deu esse lugar decadente e imundo?",
  ui_story_5066_50660201_16_dialog_content = "Alteza, por favor, se acalme.",
  ui_story_5066_50660201_17_dialog_content = "Afinal, este também é seu território e todos estão ansiosos para conhecê-lo.",
  ui_story_5066_50660201_18_dialog_content = "Então eles deveriam pagar mais impostos... Espere um segundo!",
  ui_story_5066_50660201_19_dialog_content = "Dê uma olhada nesta garota! Ela realmente é única...",
  ui_story_5066_50660201_20_dialog_content = "Sério, existe mesmo um peixe com uma aparência tão peculiar?",
  ui_story_5066_50660201_21_dialog_content = "Ela pode parecer um pouco estranha, mas como colecionável, provavelmente é super valiosa.",
  ui_story_5066_50660201_22_dialog_content = "<size=33>Tsk, o que a Connolly está fazendo aqui... Ela não deveria estar no sótão?</size>",
  ui_story_5066_50660201_23_dialog_content = "<size=33>Mas eu não esperava que o príncipe se interessasse por ela; isso pode ser uma rara oportunidade...</size>",
  ui_story_5066_50660201_24_dialog_content = "Sua Alteza, é um pouco constrangedor admitir, mas essa garota é na verdade minha irmã.",
  ui_story_5066_50660201_25_dialog_content = "Ela é praticamente um azarão em casa. Mas quando se trata de aparência única, ninguém pode superá-la.",
  ui_story_5066_50660201_26_dialog_content = "Se você estiver interessado, posso vender... oferecer ela a você agora mesmo.",
  ui_story_5066_50660201_27_dialog_content = "Ah, isso é meio conveniente. Muito atencioso da sua parte.",
  ui_story_5066_50660201_28_dialog_content = "Mas primeiro, vou dar uma olhada mais de perto para descobrir qual é o problema com ela.",
  ui_story_5066_50660201_29_dialog_content = "Já estava na hora de me divertir visitando essa cidadezinha chata. Tenho que aproveitar ao máximo.",
  ui_story_5066_50660201_30_dialog_content = "Por aqui, Alteza. Se precisar de alguma ajuda, sinta-se à vontade para dar suas ordens.",
  ui_story_5066_50660201_31_dialog_content = "A equipe do príncipe está em movimento!",
  ui_story_5066_50660201_32_dialog_content = "Pra onde ele está indo? Vamos, vamos acompanhá-lo e ver o que está acontecendo!",
  ui_story_5066_50660201_33_dialog_content = "Ah—A multidão está se movendo novamente!",
  ui_story_5066_50660201_34_dialog_content = "E-E-Espere! Estou sendo empurrado para fora...",
  ui_story_5066_50660201_35_dialog_content = "Ai!",
  ui_story_5066_50660201_36_dialog_content = "...",
  ui_story_5066_50660201_37_dialog_content = "Quem é essa garota? Ela ousa cruzar o caminho do príncipe.",
  ui_story_5066_50660201_38_dialog_content = "Uau, ela parece tão estranha; não parece um peixe de jeito nenhum!",
  ui_story_5066_50660201_39_dialog_content = "Ai! Ah não... Por favor, me diga que minhas roupas não sujaram! Eu já não tenho roupas suficientes para começar...",
  ui_story_5066_50660201_40_dialog_content = "Por que parece que todo mundo está me encarando...?",
  ui_story_5066_50660201_41_dialog_content = "Ei, você aí embaixo! Pare de olhar em volta — estou falando de você!",
  ui_story_5066_50660201_42_dialog_content = "Eca!",
  ui_story_5066_50660201_43_dialog_content = "Sua aparência um tanto feia chamou minha atenção.",
  ui_story_5066_50660201_44_dialog_content = "Aqui está o meu convite para você—tornar-se uma peça valiosa na minha coleção!",
  ui_story_5066_50660201_45_dialog_content = "Confie em mim, a vida comigo nas águas rasas é muito melhor do que ficar preso nesta cidadezinha ruim.",
  ui_story_5066_50660201_46_dialog_content = "Você sabe o que eu quero dizer, certo?",
  ui_story_5066_50660201_47_dialog_content = "Um... P-May Posso recusar, por favor?",
  ui_story_5066_50660201_48_dialog_content = "Connolly, não deixe minha boa vontade ser desperdiçada!",
  ui_story_5066_50660201_49_dialog_content = "Eu realmente falei bem de você para o príncipe para que você pudesse ter essa oportunidade!",
  ui_story_5066_50660201_50_dialog_content = "É esse o novo emprego que você estava me contando...?",
  ui_story_5066_50660201_51_dialog_content = "Você queria... <size=45>me vender para o príncipe?!</size>",
  ui_story_5066_50660201_52_dialog_content = "Não faça parecer tão ruim. Não é vender; é torná-lo um honrado companheiro real...",
  ui_story_5066_50660201_53_dialog_content = "Como sua prima, encontrei o melhor caminho para você.",
  ui_story_5066_50660201_54_dialog_content = "Caso contrário, você ficará preso em casa fazendo trabalho de empregado para sempre. Você não acha isso solitário?",
  ui_story_5066_50660201_55_dialog_content = "Solitário...? Eu já te disse antes, eu não fico solitário. Tudo que eu preciso é da minha música e do meu clarinete!",
  ui_story_5066_50660201_56_dialog_content = "Clarinete? É esse instrumento estranho na sua mão?",
  ui_story_5066_50660201_57_dialog_content = "Uau, parece um artefato antigo... bem incomum.",
  ui_story_5066_50660201_58_dialog_content = "Apresente para mim para dar uma olhada mais de perto.",
  ui_story_5066_50660201_59_dialog_content = "Ah! Eu... eu não posso deixar você!",
  ui_story_5066_50660201_60_dialog_content = "Ninguém pode me dizer não debaixo do mar! Entregue!",
  ui_story_5066_50660201_61_dialog_content = "Mas... Mas minha mãe me deixou isso...",
  ui_story_5066_50660201_62_dialog_content = "Mãe? Falando nisso, com sua aparência única, estou bastante curioso para saber como era sua mãe.",
  ui_story_5066_50660201_63_dialog_content = "Se possível, seria incrível se vocês dois pudessem ser meus colecionáveis juntos.",
  ui_story_5066_50660201_64_dialog_content = "...?",
  ui_story_5066_50660201_65_dialog_content = "Por favor, não olhe para mim, Alteza. Ela é adotada; a mãe dela não é minha...",
  ui_story_5066_50660201_66_dialog_content = "Não...",
  ui_story_5066_50660201_67_dialog_content = "O quê?!",
  ui_story_5066_50660201_68_dialog_content = "Não vou deixar você insultar a mamãe desse jeito!",
  ui_story_5066_50660201_69_dialog_content = "Ridículo!",
  ui_story_5066_50660201_70_dialog_content = "Aqui debaixo do mar, ninguém teve a audácia de falar comigo dessa maneira.",
  ui_story_5066_50660201_71_dialog_content = "Já que você não está disposto a entregar... não me culpe por ser rude!",
  ui_story_5066_50660201_72_dialog_content = "<color=#e8d9bb>O príncipe salta em direção a Connolly.</color>",
  ui_story_5066_50660201_73_dialog_content = "Não... Afaste-se de mim...!",
  ui_story_5066_50660201_74_dialog_content = "<color=#e8d9bb><size=45>Plaft—</size></color>",
  ui_story_5066_50660201_75_dialog_content = "<size=45>Aiai!!!</size>",
  ui_story_5066_50660201_76_dialog_content = "...?!",
  ui_story_5066_50660201_77_dialog_content = "...!!!",
  ui_story_5066_50660201_78_dialog_content = "Como... como ousa me atacar com uma arma?!",
  ui_story_5066_50660201_79_dialog_content = "Ah... D-Desculpe, eu não queria fazer isso...",
  ui_story_5066_50660201_80_dialog_content = "M-Mas mesmo assim... <size=30>Isso foi culpa sua...</size>",
  ui_story_5066_50660201_81_dialog_content = "O que você disse?... Guardas! Onde estão os guardas?!",
  ui_story_5066_50660201_82_dialog_content = "Pegue aquela garota ousada e malformada para mim!",
  ui_story_5066_50660201_83_dialog_content = "Sim!!!",
  ui_story_5066_50660201_84_dialog_content = "Aaah... Connolly, seu encrenqueiro! Estamos ferrados...",
  ui_story_5066_50660201_85_dialog_content = "Ah não... Acho que estou em grandes apuros agora...",
  ui_story_5066_50660201_86_dialog_content = "Estou acabado se eles me pegarem, sem dúvida... Eu tenho que fugir! Não há outra escolha para mim!",
  ui_story_5066_50660201_87_dialog_content = "Perdoe-me... Por favor, deixe-me passar!",
  ui_story_5066_50660201_88_dialog_content = "<color=#e8d9bb>Ela quer escapar da multidão, se esconder em um lugar onde ninguém possa encontrá-la.</color>",
  ui_story_5066_50660201_89_dialog_content = "<color=#e8d9bb>Mas isso é possível em uma rua movimentada e subaquática como essa...?</color>",
  ui_story_5066_50660302_1_dialog_content = "Ah... Ficar de guarda é o trabalho mais chato do mundo!",
  ui_story_5066_50660302_2_dialog_content = "Realmente não há caras maus por perto? Eu não me importaria de uma boa escaramuça agora.",
  ui_story_5066_50660302_3_dialog_content = "Comparado a lutar... Eu preferiria muito mais se pudéssemos apenas ficar juntos em paz...",
  ui_story_5066_50660302_4_dialog_content = "Sim, eu sei. Eu não estava falando sério, só estava desabafando.",
  ui_story_5066_50660302_5_dialog_content = "Tá bom...",
  ui_story_5066_50660302_6_dialog_content = "Embora eu não me importasse se o Connolly viesse conversar um pouco também!",
  ui_story_5066_50660302_7_dialog_content = "Faz um tempo que não a vemos, né?",
  ui_story_5066_50660302_8_dialog_content = "Ouvi dizer... A família dela está esperando um convidado importante... Ela provavelmente está ocupada cuidando da casa.",
  ui_story_5066_50660302_9_dialog_content = "Cuidando da casa?",
  ui_story_5066_50660302_10_dialog_content = "Ah, se ela ficou presa em casa todo esse tempo, tenho certeza de que sua tia irritante tem tornado a vida dela miserável.",
  ui_story_5066_50660302_11_dialog_content = "Se eu tiver a chance, eu realmente quero dar um tapa nela uma ou duas vezes por Connolly!",
  ui_story_5066_50660302_12_dialog_content = "Eu... não te impediria de fazer isso.",
  ui_story_5066_50660302_13_dialog_content = "Connolly tem nos ajudado com nossos recados todo esse tempo, mas não tivemos a chance de retribuir... Isso está realmente começando a me incomodar...",
  ui_story_5066_50660302_14_dialog_content = "Pois é!",
  ui_story_5066_50660302_15_dialog_content = "Ela também não aceita dinheiro por isso. Ela até diz que é grata a nós...",
  ui_story_5066_50660302_16_dialog_content = "Ah... Eu realmente não preciso de dinheiro para fazer recados para você...",
  ui_story_5066_50660302_17_dialog_content = "Eu... eu só fico feliz em sair de casa de vez em quando...",
  ui_story_5066_50660302_18_dialog_content = "Afinal... Minha tia me repreendia na maior parte do tempo sempre que eu estava em casa...",
  ui_story_5066_50660302_19_dialog_content = "Então, por favor... me chame se tiver algum recado que precise que eu faça!",
  ui_story_5066_50660302_20_dialog_content = "Ela realmente é uma boa menina, hein.",
  ui_story_5066_50660302_21_dialog_content = "Ela não é nada como aquela bruxa gananciosa e astuta para quem costumávamos trabalhar!",
  ui_story_5066_50660302_22_dialog_content = "<size=45>Ohhhhhh!</size>",
  ui_story_5066_50660302_23_dialog_content = "O que é todo esse barulho? Está acontecendo algo lá?",
  ui_story_5066_50660302_24_dialog_content = "Sim... E parece bem animado também.",
  ui_story_5066_50660302_25_dialog_content = "Eu realmente quero ir dar uma olhada! Quanto tempo mais temos que ficar aqui de guarda?!",
  ui_story_5066_50660302_26_dialog_content = "Eu sei como você se sente... Mas ainda é muito cedo no nosso turno...",
  ui_story_5066_50660302_27_dialog_content = "Enfim, esse tipo de confusão é bem comum.",
  ui_story_5066_50660302_28_dialog_content = "Com um rei tão arrogante e um príncipe pomposo, os habitantes do mar têm enfrentado tempos difíceis.",
  ui_story_5066_50660302_29_dialog_content = "Será que o príncipe estúpido foi atacado por moradores irritados? Agora, isso seria interessante.",
  ui_story_5066_50660302_30_dialog_content = "Se algo assim realmente acontecesse bem na minha frente...",
  ui_story_5066_50660302_31_dialog_content = "Eu só fingiria que não vi nada...",
  ui_story_5066_50660302_32_dialog_content = "Aqui!",
  ui_story_5066_50660302_33_dialog_content = "Ei, vocês dois!",
  ui_story_5066_50660302_34_dialog_content = "Os guardas do príncipe?",
  ui_story_5066_50660302_35_dialog_content = "Não me diga que eu estava certo...",
  ui_story_5066_50660302_36_dialog_content = "Você viu uma garota de aparência peculiar correndo por aqui, alguém carregando um clarinete?",
  ui_story_5066_50660302_37_dialog_content = "...",
  ui_story_5066_50660302_38_dialog_content = "(É Connolly...)",
  ui_story_5066_50660302_39_dialog_content = "(O que o príncipe quer com ela?)",
  ui_story_5066_50660302_40_dialog_content = "(Seja lá qual for o plano dele, não podemos deixá-lo conseguir o que quer.)",
  ui_story_5066_50660302_41_dialog_content = "Não se preocupe, eu não esperava que vocês a tivessem visto. Vocês dois são membros da equipe de busca agora! Comecem a procurar a partir daqui!",
  ui_story_5066_50660302_42_dialog_content = "Uh... May podemos perguntar o que aconteceu agora há pouco...?",
  ui_story_5066_50660302_43_dialog_content = "O que aconteceu? Heh, aquela garota de aparência peculiar realmente ousou atacar o príncipe!",
  ui_story_5066_50660302_44_dialog_content = "Isso é sem precedentes!",
  ui_story_5066_50660302_45_dialog_content = "Ela vai se arrepender quando eu pegá-la!",
  ui_story_5066_50660302_46_dialog_content = "<size=33>Boa, Connolly! Muito bom!</size>",
  ui_story_5066_50660302_47_dialog_content = "O que você acabou de dizer?",
  ui_story_5066_50660302_48_dialog_content = "Ah, nada demais, apenas faremos o nosso melhor em nossos trabalhos.",
  ui_story_5066_50660302_49_dialog_content = "Bem, então mexam suas bundas!",
  ui_story_5066_50660302_50_dialog_content = "Sim, senhor!",
  ui_story_5066_50660302_51_dialog_content = "...",
  ui_story_5066_50660302_52_dialog_content = "Ah, não, Connolly está em sério perigo desta vez.",
  ui_story_5066_50660302_53_dialog_content = "Você está certo... Precisamos encontrá-la imediatamente...",
  ui_story_5066_50660302_54_dialog_content = "E precisamos encontrá-la antes que esses guardas o façam, ou as coisas vão piorar ainda mais.",
  ui_story_5066_50660401_1_dialog_content = "Arf, arf...",
  ui_story_5066_50660401_2_dialog_content = "Acho que... os perdi...",
  ui_story_5066_50660401_3_dialog_content = "Siga por aqui! Procure!",
  ui_story_5066_50660401_4_dialog_content = "Ah... Oh não...",
  ui_story_5066_50660401_5_dialog_content = "Se eu me encolher e me esconder bem aqui... Eles não deveriam ser capazes de me encontrar...",
  ui_story_5066_50660401_6_dialog_content = "Meu coração... Está batendo tão rápido... Sinto que não consigo respirar...",
  ui_story_5066_50660401_7_dialog_content = "Por aqui! Aqui!",
  ui_story_5066_50660401_8_dialog_content = "Ahhh... Por favor, não me encontre, não me encontre, não me encontre...",
  ui_story_5066_50660401_9_dialog_content = "Você não precisava correr, não é?",
  ui_story_5066_50660401_10_dialog_content = "...?!",
  ui_story_5066_50660401_11_dialog_content = "Faça um pacto comigo e todos os problemas desaparecerão.",
  ui_story_5066_50660401_12_dialog_content = "Você, está na hora de fazer uma escolha...",
  ui_story_5066_50660401_13_dialog_content = "M-Mas…",
  ui_story_5066_50660401_14_dialog_content = "As coisas já estão assim; o que há para hesitar?",
  ui_story_5066_50660401_15_dialog_content = "Eu sei... Mas...",
  ui_story_5066_50660401_16_dialog_content = "<size=33>A ideia de... me envolver com uma criatura tão estranha...</size>",
  ui_story_5066_50660401_17_dialog_content = "<size=33>Isso também não parece muito agradável...</size>",
  ui_story_5066_50660401_18_dialog_content = "Alto e claro, ouvi suas palavras.",
  ui_story_5066_50660401_19_dialog_content = "Ah... Desculpe! Eu... Eu não quis dizer isso dessa forma...",
  ui_story_5066_50660401_20_dialog_content = "Os guardas foram para lá! Vamos verificar as coisas por aqui!",
  ui_story_5066_50660401_21_dialog_content = "Certo. Eu posso sentir... Ela está por perto...",
  ui_story_5066_50660401_22_dialog_content = "...",
  ui_story_5066_50660401_23_dialog_content = "Ah não, gastei muito tempo conversando com aquela voz...",
  ui_story_5066_50660401_24_dialog_content = "Esqueci completamente do perigo ao meu redor...",
  ui_story_5066_50660401_25_dialog_content = "*Sniff*... D-Eu realmente tenho que fazer parte da coleção do príncipe...?",
  ui_story_5066_50660401_26_dialog_content = "É a Connolly! Finalmente a encontramos!",
  ui_story_5066_50660401_27_dialog_content = "Ufa... Graças a Deus... Chegamos nela antes daqueles caras...",
  ui_story_5066_50660401_28_dialog_content = "Ahn???",
  ui_story_5066_50660401_29_dialog_content = "Você está bem, Connolly? Eles não te machucaram, não é?",
  ui_story_5066_50660401_30_dialog_content = "É-é você, Dayna... E Robyn também?",
  ui_story_5066_50660401_31_dialog_content = "... *acena*",
  ui_story_5066_50660401_32_dialog_content = "Ah, é tão bom ver vocês dois! Mas me desculpe... Eu realmente não tenho tempo para ajudar com os seus recados hoje...",
  ui_story_5066_50660401_33_dialog_content = "Agora não é hora para isso, Connolly.",
  ui_story_5066_50660401_34_dialog_content = "Precisamos sair daqui antes que os guardas do príncipe te encontrem!",
  ui_story_5066_50660401_35_dialog_content = "Como você sabe sobre o príncipe? Oh não... Não me diga que este lugar também não é seguro?",
  ui_story_5066_50660401_36_dialog_content = "Se eles me encontrarem aqui... O-O que devo fazer...?",
  ui_story_5066_50660401_37_dialog_content = "Não se preocupe... Dayna teve uma ótima ideia...",
  ui_story_5066_50660401_38_dialog_content = "R... Sério?",
  ui_story_5066_50660401_39_dialog_content = "Sim! Vamos esperar os guardas aparecerem, depois dar a eles informações erradas e mandá-los procurar em outro lugar.",
  ui_story_5066_50660401_40_dialog_content = "Isso deve te dar tempo suficiente para encontrar um lugar seguro para se esconder.",
  ui_story_5066_50660401_41_dialog_content = "Ah... Muito obrigado, mas... Eu não sei como retribuir a vocês dois...",
  ui_story_5066_50660401_42_dialog_content = "Tch, não adianta muito dizer isso, né?",
  ui_story_5066_50660401_43_dialog_content = "Você tem nos ajudado por tanto tempo... Nós é que não retribuímos a você...",
  ui_story_5066_50660401_44_dialog_content = "Mas...",
  ui_story_5066_50660401_45_dialog_content = "Tudo bem, tudo bem, deixe isso para outra hora. Você vai perder sua chance se não se mexer.",
  ui_story_5066_50660401_46_dialog_content = "Agora vá... E não olhe para trás...",
  ui_story_5066_50660401_47_dialog_content = "E-Entendi!",
  ui_story_5066_50660401_48_dialog_content = "Apressem-se, bando de inúteis! Por que ainda estão enrolando aqui?",
  ui_story_5066_50660401_49_dialog_content = "A informação diz que ela está neste beco, certo? Se estiver errado, você enfrentará consequências!",
  ui_story_5066_50660401_50_dialog_content = "Heh, acho que chegamos tarde demais.",
  ui_story_5066_50660401_51_dialog_content = "Então... O que devemos fazer, Dayna?",
  ui_story_5066_50660401_52_dialog_content = "Temos que bloquear a entrada desse beco, para que Connolly tenha tempo suficiente para escapar.",
  ui_story_5066_50660401_53_dialog_content = "De qualquer maneira, não podemos deixá-los colocar as mãos nela.",
  ui_story_5066_50660401_54_dialog_content = "Certo.",
  ui_story_5066_50660401_55_dialog_content = "Hum... J-Só um momento por favor...",
  ui_story_5066_50660401_56_dialog_content = "Eu... eu realmente sou grato pela sua ajuda... Sinceramente...",
  ui_story_5066_50660401_57_dialog_content = "Mas você... Você realmente não precisa ir tão longe... por alguém como eu...",
  ui_story_5066_50660401_58_dialog_content = "Eu não... quero causar nenhum problema para nenhum de vocês...",
  ui_story_5066_50660401_59_dialog_content = "Não nos faça parecer estranhos, Connolly! Você vai magoar nossos sentimentos!",
  ui_story_5066_50660401_60_dialog_content = "Na verdade... Nós queríamos... retribuir sua gentileza há muito tempo...",
  ui_story_5066_50660401_61_dialog_content = "Sim, mas você não facilita para nós, já que está sempre se escondendo de todo mundo.",
  ui_story_5066_50660401_62_dialog_content = "Às vezes, eu me preocupo que sua tia tenha te trancado, e isso me dá vontade de ir te libertar.",
  ui_story_5066_50660401_63_dialog_content = "Então, por favor... Vamos ajudá-lo desta vez...",
  ui_story_5066_50660401_64_dialog_content = "Eu vou para a esquerda e você para a direita. Vamos lá, Robyn.",
  ui_story_5066_50660401_65_dialog_content = "Tudo bem, Dayna.",
  ui_story_5066_50660402_1_dialog_content = "Eu... Eu consegui escapar...?",
  ui_story_5066_50660402_2_dialog_content = "Obrigado, Dayna e Robyn...",
  ui_story_5066_50660402_3_dialog_content = "...",
  ui_story_5066_50660402_4_dialog_content = "Por causa deles, eu... eu não posso deixar que me capturem!",
  ui_story_5066_50660402_5_dialog_content = "*ofegante* Eu... Eu acho que devo estar seguro aqui...",
  ui_story_5066_50660402_6_dialog_content = "...",
  ui_story_5066_50660402_7_dialog_content = "Ah...",
  ui_story_5066_50660402_8_dialog_content = "Um guarda passando? Parece que... ele não me notou...",
  ui_story_5066_50660402_9_dialog_content = "Ainda assim... O rei e o príncipe controlam toda essa área... Onde posso me esconder por aqui?",
  ui_story_5066_50660402_10_dialog_content = "Por mais que eu não suportasse... Eu não consigo nem voltar para o sótão na casa da minha tia...",
  ui_story_5066_50660402_11_dialog_content = "Meu primo vai encontrar um jeito de me apresentar ao príncipe...",
  ui_story_5066_50660402_12_dialog_content = "...",
  ui_story_5066_50660402_13_dialog_content = "Não sou forte o suficiente para enfrentar todos eles sozinho...",
  ui_story_5066_50660402_14_dialog_content = "O que significa... que só me resta uma escolha, não é...?",
  ui_story_5066_50660402_15_dialog_content = "Para me chamar, toque isso com seu clarinete.",
  ui_story_5066_50660402_16_dialog_content = "Eu realmente estou prestes a tocar... Ainda estou tão nervoso...",
  ui_story_5066_50660402_17_dialog_content = "Mas afinal, mamãe me deixou com esta clarineta...",
  ui_story_5066_50660402_18_dialog_content = "Eu tenho que... ser corajoso...",
  ui_story_5066_50660402_19_dialog_content = "*Tocando o clarinete*",
  ui_story_5066_50660402_20_dialog_content = "...",
  ui_story_5066_50660402_21_dialog_content = "Estou feliz em ver você finalmente tomar uma decisão...",
  ui_story_5066_50660402_22_dialog_content = "Venha e faça um pacto comigo agora!",
  ui_story_5066_50660402_23_dialog_content = "C-Posso pedir um segundo...?",
  ui_story_5066_50660402_24_dialog_content = "Neste momento, não há como voltar atrás para você.",
  ui_story_5066_50660402_25_dialog_content = "Eu... Eu não vou me arrepender de nada, mas... Eu só quero ter certeza de algo primeiro.",
  ui_story_5066_50660402_26_dialog_content = "Você não vai... me fazer fazer algo terrível, né?",
  ui_story_5066_50660402_27_dialog_content = "Meu objetivo final é que você seja a rainha, governando todo o reino subaquático.",
  ui_story_5066_50660402_28_dialog_content = "Terrível ou não, tudo depende da sua própria escolha.",
  ui_story_5066_50660402_29_dialog_content = "Mas... Se eu me tornar uma rainha ou algo assim... Não vou me destacar demais?",
  ui_story_5066_50660402_30_dialog_content = "Eu só... não quero fazer nada muito chamativo...",
  ui_story_5066_50660402_31_dialog_content = "Um pedido estranho... Eu pensei que se alguém pudesse controlar meu poder, eles gostariam de exibir sua força para o mundo.",
  ui_story_5066_50660402_32_dialog_content = "Mas você... Bem, não é nada demais; você pode ser uma rainha discreta se é isso que deseja.",
  ui_story_5066_50660402_33_dialog_content = "T-Tudo bem então. Vá em frente e... pegue o preço que quiser de mim...",
  ui_story_5066_50660402_34_dialog_content = "Preço?",
  ui_story_5066_50660402_35_dialog_content = "Você não vai levar meus olhos ou meu nariz? ... Ou talvez você queira minhas orelhas?",
  ui_story_5066_50660402_36_dialog_content = "*soluçando* Eu não me importo se você tiver que me comer... Contanto que eu possa sair dessa situação perigosa...",
  ui_story_5066_50660402_37_dialog_content = "Já disse antes... Eu nunca consumo seres mortais!",
  ui_story_5066_50660402_38_dialog_content = "Boo-hoo! Eu... me desculpe! Eu esqueci totalmente...",
  ui_story_5066_50660402_39_dialog_content = "Eu não preciso que você pague nenhum preço.",
  ui_story_5066_50660402_40_dialog_content = "Fazer um pacto com você é apenas por causa da sua singularidade e da relíquia que você possui.",
  ui_story_5066_50660402_41_dialog_content = "Quando a partitura do clarinete for tocada, eu vou ajudá-lo a dominar os mares.",
  ui_story_5066_50660402_42_dialog_content = "Dito isso, ainda restam dúvidas em sua mente?",
  ui_story_5066_50660402_43_dialog_content = "Ah... Acho que não...",
  ui_story_5066_50660402_44_dialog_content = "Mas isso não é... Bom demais para ser verdade...?",
  ui_story_5066_50660402_45_dialog_content = "Não precisa se preocupar; você está prestes a começar um novo capítulo em sua vida. Aproveite ao máximo.",
  ui_story_5066_50660402_46_dialog_content = "<size=45>Neste momento, o pacto é formalmente feito!</size>",
  ui_story_5066_50660402_47_dialog_content = "...",
  ui_story_5066_50660501_1_dialog_content = "<color=#e8d9bb>Estrondo—Estrondo—</color>",
  ui_story_5066_50660501_2_dialog_content = "Esses guardas são mais resistentes do que eu pensava.",
  ui_story_5066_50660501_3_dialog_content = "Vão se engasgar com algas, seus idiotas!",
  ui_story_5066_50660501_4_dialog_content = "<color=#e8d9bb>Estrondo—Estalo—</color>",
  ui_story_5066_50660501_5_dialog_content = "Você não está errado... Eles são bem persistentes...",
  ui_story_5066_50660501_6_dialog_content = "Mas não podemos deixá-los passar por nós...",
  ui_story_5066_50660501_7_dialog_content = "Huh, isso é uma grande surpresa.",
  ui_story_5066_50660501_8_dialog_content = "Nessas águas, há realmente aqueles que ousam desafiar a mim e aos meus guardas!?",
  ui_story_5066_50660501_9_dialog_content = "Parece que minha visita hoje foi bem programada!",
  ui_story_5066_50660501_10_dialog_content = "Se deixarmos isso passar, quem sabe que tipo de problemas podem surgir?",
  ui_story_5066_50660501_11_dialog_content = "Guardas, estão morrendo de fome ou algo assim? Depressa, capturem esses dois traidores!",
  ui_story_5066_50660501_12_dialog_content = "<color=#e8d9bb>Estrondo—Estalo—</color>",
  ui_story_5066_50660501_13_dialog_content = "Você está mil anos adiantado para me desafiar!",
  ui_story_5066_50660501_14_dialog_content = "Mas eu estava ficando um pouco entediado, então vamos nos divertir!",
  ui_story_5066_50660501_15_dialog_content = "<color=#e8d9bb>Estrondo—Estalo—</color>",
  ui_story_5066_50660501_16_dialog_content = "Lutar... Não é realmente um problema para nós...",
  ui_story_5066_50660501_17_dialog_content = "Eu só queria saber como o Connolly está agora...",
  ui_story_5066_50660501_18_dialog_content = "<color=#e8d9bb>O som de um clarinete ecoa.</color>",
  ui_story_5066_50660501_19_dialog_content = "Qual é o lance dessa melodia sinistra?",
  ui_story_5066_50660501_20_dialog_content = "Ei, guardas, vão e investiguem...",
  ui_story_5066_50660501_21_dialog_content = "...",
  ui_story_5066_50660501_22_dialog_content = "<size=45>O que... o que é isso?!</size>",
  ui_story_5066_50660501_23_dialog_content = "É aquela Connolly? O que aconteceu com ela?!",
  ui_story_5066_50660501_24_dialog_content = "Parece que... Ela ganhou novos poderes... Será que ela fez isso apenas para nos ajudar?",
  ui_story_5066_50660501_25_dialog_content = "Hah! Tudo blefe; apenas parece assustador.",
  ui_story_5066_50660501_26_dialog_content = "Na verdade, isso me poupou trabalho. Vamos, guardas, vão buscá-la!",
  ui_story_5066_50660501_27_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660501_28_dialog_content = "Huh... Aaaaah... o que são esses tentáculos?!",
  ui_story_5066_50660501_29_dialog_content = "Não! Por favor! Me coloque no chão!",
  ui_story_5066_50660501_30_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660501_31_dialog_content = "Eu não pretendo fazer isso... Estou apenas seguindo as ordens do príncipe... Por favor, poupe-me!",
  ui_story_5066_50660501_32_dialog_content = "Eu também não quero lutar com você! É... é tudo por causa do príncipe! Ele me fez fazer isso!",
  ui_story_5066_50660501_33_dialog_content = "Pare! Quem disse que vocês podiam fugir?! Seu bando inútil, parem! Droga...",
  ui_story_5066_50660501_34_dialog_content = "...",
  ui_story_5066_50660501_35_dialog_content = "Hehe. Bom, muito bom...",
  ui_story_5066_50660501_36_dialog_content = "Ouse me desafiar e certamente pagará o preço!",
  ui_story_5066_50660501_37_dialog_content = "De qualquer forma, os impostos que esta pequena cidade decadente paga já são lamentavelmente baixos desde o início.",
  ui_story_5066_50660501_38_dialog_content = "Se você ainda não obedecer, não vejo motivo para a existência desta cidade!",
  ui_story_5066_50660501_39_dialog_content = "...",
  ui_story_5066_50660501_40_dialog_content = "Ei, você... garota de aparência estranha, já chega!",
  ui_story_5066_50660501_41_dialog_content = "Se o príncipe voltar e contar ao rei para enviar um exército para destruir nossa cidade... você pode suportar as consequências?",
  ui_story_5066_50660501_42_dialog_content = "Além disso, aquele que você ofendeu não é outro senão o nobre Príncipe!",
  ui_story_5066_50660501_43_dialog_content = "Você, com seu status humilde, como pode agir com tanto desrespeito?",
  ui_story_5066_50660501_44_dialog_content = "...",
  ui_story_5066_50660501_45_dialog_content = "(Eu sabia... Chamar atenção assim realmente não combina comigo...)",
  ui_story_5066_50660501_46_dialog_content = "(Eu... estraguei tudo de novo, não foi...?)",
  ui_story_5066_50660501_47_dialog_content = "(Se eu só me preocupar com o perigo iminente... Será que as consequências continuarão sendo tão ruins...?)",
  ui_story_5066_50660501_48_dialog_content = "Eu... eu não quis fazer isso... M-Mas...",
  ui_story_5066_50660501_49_dialog_content = "Ei, Connolly! Você não precisa se desculpar com esses idiotas de jeito nenhum!",
  ui_story_5066_50660501_50_dialog_content = "Esqueceu como aquele príncipe pomposo te atacou? Por que ainda tem medo dele?!",
  ui_story_5066_50660501_51_dialog_content = "Você vai ser zoado pelo resto da sua vida se não mudar!",
  ui_story_5066_50660501_52_dialog_content = "Tolerância e compromisso... só te levarão até certo ponto...",
  ui_story_5066_50660501_53_dialog_content = "Isso é inegável...",
  ui_story_5066_50660501_54_dialog_content = "Isso mesmo! Basta olhar todas as coisas ultrajantes que o príncipe fez nesta pequena cidade!",
  ui_story_5066_50660501_55_dialog_content = "Se ele não quer nos governar, tudo bem por mim!",
  ui_story_5066_50660501_56_dialog_content = "Já estava na hora de escolhermos um novo governante mesmo!",
  ui_story_5066_50660501_57_dialog_content = "...",
  ui_story_5066_50660501_58_dialog_content = "<size=33>Bem, eu acho... que o que ela disse realmente faz sentido...</size>",
  ui_story_5066_50660501_59_dialog_content = "<size=33>Sinceramente, eu também já cansei...</size>",
  ui_story_5066_50660501_60_dialog_content = "Se aumentarem os impostos novamente, não sobreviveremos; será um beco sem saída de qualquer forma.",
  ui_story_5066_50660501_61_dialog_content = "Se possível, também podemos conseguir um novo governante, certo?",
  ui_story_5066_50660501_62_dialog_content = "<size=45>Ultrajante, todos vocês estão sendo ultrajantes!</size>",
  ui_story_5066_50660501_63_dialog_content = "Acham mesmo que vocês, plebeus, podem abalar nosso reinado com algumas palavras? Isso não vai acontecer!",
  ui_story_5066_50660501_64_dialog_content = "Hoje, vou dar um exemplo e executar todos vocês rebeldes que falam fora de hora!",
  ui_story_5066_50660501_65_dialog_content = "Um... Fui eu quem causou toda essa confusão...",
  ui_story_5066_50660501_66_dialog_content = "Todos estavam falando por mim até agora...",
  ui_story_5066_50660501_67_dialog_content = "Mas agora que eu tenho esse poder incrível... Eu... Eu não sou mais o mesmo que costumava ser...",
  ui_story_5066_50660501_68_dialog_content = "Dessa vez... É minha vez de proteger todos!",
  ui_story_5066_50660602_1_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50660602_2_dialog_content = "Ah... isso dói...",
  ui_story_5066_50660602_3_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50660602_4_dialog_content = "Eca... não, por favor, pare!",
  ui_story_5066_50660602_5_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660602_6_dialog_content = "Chega... Já chega!",
  ui_story_5066_50660602_7_dialog_content = "Eu perdi! Eu me rendo! Não... Eu não perdi para você...",
  ui_story_5066_50660602_8_dialog_content = "Perdi para esse monstro de tentáculos!",
  ui_story_5066_50660602_9_dialog_content = "De onde diabos você adquiriu tanto poder?!",
  ui_story_5066_50660602_10_dialog_content = "Bem... uh, eu não sei como explicar isso...",
  ui_story_5066_50660602_11_dialog_content = "Talvez seja melhor vocês verem por si mesmos?",
  ui_story_5066_50660602_12_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660602_13_dialog_content = "...",
  ui_story_5066_50660602_14_dialog_content = "...?!",
  ui_story_5066_50660602_15_dialog_content = "O quê?! É...!",
  ui_story_5066_50660602_16_dialog_content = "Poderia ser... aquele da antiga lenda, o templo...",
  ui_story_5066_50660602_17_dialog_content = "Não, não, não, absolutamente impossível! Como poderia essa garota estranha...",
  ui_story_5066_50660602_18_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50660602_19_dialog_content = "<color=#e8d9bb>Sploosh—</color>",
  ui_story_5066_50660602_20_dialog_content = "Ah... Argh...",
  ui_story_5066_50660602_21_dialog_content = "Como ousa... Como você ousa... Espere só, o exército do reino virá aqui... para acertar as contas e lavar minha vergonha!",
  ui_story_5066_50660602_22_dialog_content = "Ufa... Acho que finalmente cuidei deles... certo?",
  ui_story_5066_50660602_23_dialog_content = "Claro que sim, Connolly! A maneira como você fez o príncipe voar foi incrível! Tenha mais autoconfiança!",
  ui_story_5066_50660602_24_dialog_content = "É verdade... Nem mesmo o Dayna poderia ter feito algo assim...",
  ui_story_5066_50660602_25_dialog_content = "E... Não foi tão impressionante... Por favor, não zombem de mim, vocês dois...",
  ui_story_5066_50660602_26_dialog_content = "Nós não estamos zombando de você de forma alguma.",
  ui_story_5066_50660602_27_dialog_content = "Então, que tipo de coisa é essa, Connolly? Algum tipo de monstro?",
  ui_story_5066_50660602_28_dialog_content = "Dayna... Talvez isso tenha sido... Um pouco rude...",
  ui_story_5066_50660602_29_dialog_content = "Ops, desculpe por isso! É mais como seu amigo, certo?",
  ui_story_5066_50660602_30_dialog_content = "Uh... Para ser sincero, eu também não sei realmente o que é isso...",
  ui_story_5066_50660602_31_dialog_content = "Mas ele continua se chamando de \"o grande Senhor Aqua\".",
  ui_story_5066_50660602_32_dialog_content = "Então eu imagino... Deve ser uma figura bastante poderosa de algum tipo, certo?",
  ui_story_5066_50660602_33_dialog_content = "<size=45>Senhor Aqua? É o... Senhor Aqua?!</size>",
  ui_story_5066_50660602_34_dialog_content = "Hã? Desculpe-me... Você conhece o Lorde Aqua?",
  ui_story_5066_50660602_35_dialog_content = "Senhor Aqua... Ele foi o grande governante que já dominou o mundo subaquático!",
  ui_story_5066_50660602_36_dialog_content = "Antes do brutal Rei Tritão chegar às águas rasas, ele costumava governar tudo por aqui...",
  ui_story_5066_50660602_37_dialog_content = "Dizem que até hoje, os restos de seu templo com poder oculto ainda existem.",
  ui_story_5066_50660602_38_dialog_content = "<anim type=Shake>ç åï|'H>■...</anim>",
  ui_story_5066_50660602_39_dialog_content = "As palavras sagradas, são as palavras sagradas! O Senhor está prestes a nos transmitir as palavras sagradas...",
  ui_story_5066_50660602_40_dialog_content = "...",
  ui_story_5066_50660602_41_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5066_50660602_42_dialog_content = "<color=#e8d9bb>Com um olhar de fé inabalável, o velhote se ajoelha em reverência...</color>",
  ui_story_5066_50660602_43_dialog_content = "<color=#e8d9bb>Como uma onda, o restante dos habitantes submarinos começam a se prostrar diante deste outrora grande governante...</color>",
  ui_story_5066_50660701_1_dialog_content = "É tudo culpa sua por enviar o Connolly para fazer recados, e agora se transformou em um desastre total!",
  ui_story_5066_50660701_2_dialog_content = "Como eu poderia saber que ela ousaria... ser tão imprudente e desafiadora?",
  ui_story_5066_50660701_3_dialog_content = "Se isso afetar a carreira do nosso filho, não há como você compensar isso.",
  ui_story_5066_50660701_4_dialog_content = "Pare de falar sobre isso; apenas pare! Essa maldição, assim que encontrarmos ela, precisaremos dar uma boa lição nela!",
  ui_story_5066_50660701_5_dialog_content = "...",
  ui_story_5066_50660701_6_dialog_content = "O que está acontecendo? Por que todos estão ajoelhados no chão?",
  ui_story_5066_50660701_7_dialog_content = "Olhe... olhe para lá.",
  ui_story_5066_50660701_8_dialog_content = "<anim type=Shake>âŠâ €په؛‹Šèã</anim>",
  ui_story_5066_50660701_9_dialog_content = "Isso é... Eu ouvi falar. Esse é o Grande Senhor dos tempos antigos!",
  ui_story_5066_50660701_10_dialog_content = "E ao lado do senhor está... Connolly?! Como isso é possível?",
  ui_story_5066_50660701_11_dialog_content = "Não se preocupe se é possível ou não. Ajoelhe-se rapidamente, ou estaremos em apuros!",
  ui_story_5066_50660701_12_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5066_50660701_13_dialog_content = "<anim type=Shake>е­‘гдё —пе›Œâ€¦в¦</anim>",
  ui_story_5066_50660701_14_dialog_content = "Mesmo que houvesse muitas vozes diferentes vindo da multidão até agora...",
  ui_story_5066_50660701_15_dialog_content = "Parece que todos mais ou menos aceitam este Aqua Lord.",
  ui_story_5066_50660701_16_dialog_content = "O problema, pelo visto... É que ninguém consegue entender o que está sendo dito.",
  ui_story_5066_50660701_17_dialog_content = "Podemos não ser capazes de entender, mas isso não deve ser um problema para o Connolly!",
  ui_story_5066_50660701_18_dialog_content = "Importa-se de traduzir para nós?",
  ui_story_5066_50660701_19_dialog_content = "Ah... Eu não percebi que mais ninguém conseguia entender...",
  ui_story_5066_50660701_20_dialog_content = "A fala dele tem o mesmo efeito que a melodia daquela partitura de música de antes...",
  ui_story_5066_50660701_21_dialog_content = "Será que é por isso... que me escolheu?",
  ui_story_5066_50660701_22_dialog_content = "B-Bem... Se ninguém se opuser...",
  ui_story_5066_50660701_23_dialog_content = "Vou traduzir as palavras do Senhor Aqua para que todos possam ouvir...",
  ui_story_5066_50660701_24_dialog_content = "<anim type=Shake>éµè Œâ€...¦â€¦ å“š■</anim>",
  ui_story_5066_50660701_25_dialog_content = "O Senhor Aqua diz que deseja retornar a este mundo e recuperar esta cidade do Rei Tritão usurpador.",
  ui_story_5066_50660701_26_dialog_content = "<anim type=Shake>FzI¦م€ ...■چcJ;@ڑ â– é‡Œ</anim>",
  ui_story_5066_50660701_27_dialog_content = "E... Por causa da minha habilidade inata de me comunicar com ele, o Aqua Lord formou um pacto comigo...",
  ui_story_5066_50660701_28_dialog_content = "Para servir como seu mensageiro e cumprir sua vontade...",
  ui_story_5066_50660701_29_dialog_content = "<anim type=Shake>…...و°i%µç·tu€…â€i... €…وˆگم€■</anim>",
  ui_story_5066_50660701_30_dialog_content = "Huh...?!",
  ui_story_5066_50660701_31_dialog_content = "(Uh-oh...)",
  ui_story_5066_50660701_32_dialog_content = "(Ele quer que eu conte a todos... Que eu sou a Aqua Queen...?)",
  ui_story_5066_50660701_33_dialog_content = "(Eu não acho... que posso dizer algo assim...)",
  ui_story_5066_50660701_34_dialog_content = "(Já disse... Que não quero fazer nada que me faça destacar...)",
  ui_story_5066_50660701_35_dialog_content = "<anim type=Shake>еâ€...eåŸœ■å€âŠâ</anim>",
  ui_story_5066_50660701_36_dialog_content = "<size=33>Chega, Aqua Lord... Mais exigências e você só vai assustar a todos...</size>",
  ui_story_5066_50660701_37_dialog_content = "... (insatisfeito)",
  ui_story_5066_50660701_38_dialog_content = "Hã...",
  ui_story_5066_50660701_39_dialog_content = "E-Está tudo bem... Se eu parar de traduzir agora?",
  ui_story_5066_50660701_40_dialog_content = "...",
  ui_story_5066_50660701_41_dialog_content = "Claro, Porta-voz do Divino! Ou devemos nos dirigir a você como... o Queen?",
  ui_story_5066_50660701_42_dialog_content = "<size=45>Uhhh... Queen?!</size>",
  ui_story_5066_50660701_43_dialog_content = "I-Isso é um pouco ousado, você não acha...?",
  ui_story_5066_50660701_44_dialog_content = "<size=33>Eu nem mesmo traduzi aquela última parte, mas de alguma forma... Todos já começaram... a me chamar de \"rainha\"?</size>",
  ui_story_5066_50660701_45_dialog_content = "Isso mesmo, Vossa Majestade, seu poder é evidente para todos!",
  ui_story_5066_50660701_46_dialog_content = "Aqueles desprezíveis guardas Tritões estão rondando por aí. Você realmente deveria ensinar-lhes uma lição!",
  ui_story_5066_50660701_47_dialog_content = "Você tem nosso total apoio!",
  ui_story_5066_50660701_48_dialog_content = "Ah... Bem, se as coisas vão continuar assim...",
  ui_story_5066_50660701_49_dialog_content = "Mesmo que eu não estivesse fazendo isso pelo bem de mais ninguém, ou mesmo pelo meu próprio...",
  ui_story_5066_50660701_50_dialog_content = "Ainda gostaria de terminar de limpar por aqui...",
  ui_story_5066_50660702_1_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50660702_2_dialog_content = "Ufa... Esse foi o último deles. Esses guardas Tritões devem ter ido embora agora...",
  ui_story_5066_50660702_3_dialog_content = "Esses bandidos fedorentos já deveriam ter sido expulsos da cidade há muito tempo!",
  ui_story_5066_50660702_4_dialog_content = "Infelizmente, os biscoitos de Connolly não chegaram. Que decepção...",
  ui_story_5066_50660702_5_dialog_content = "Ei Connolly... Você não parece muito feliz... Está tudo bem?",
  ui_story_5066_50660702_6_dialog_content = "Ah, desculpe! Dá pra perceber só de olhar, né...?",
  ui_story_5066_50660702_7_dialog_content = "Agora mesmo... Todos começaram a me chamar de rainha...",
  ui_story_5066_50660702_8_dialog_content = "Mas... Eu não quero ser esse tipo de rainha estranha...",
  ui_story_5066_50660702_9_dialog_content = "Eu... Eu preferiria passar meus dias sozinho no sótão, com apenas minha música para me fazer companhia...",
  ui_story_5066_50660702_10_dialog_content = "Eu realmente não entendo, mas apoio de todo coração a sua decisão.",
  ui_story_5066_50660702_11_dialog_content = "Mas... O Tritão...",
  ui_story_5066_50660702_12_dialog_content = "Tá tudo bem, Robyn. Não assuste Connolly.",
  ui_story_5066_50660702_13_dialog_content = "Tá tudo bem... Eu tô ciente da situação em que me encontro...",
  ui_story_5066_50660702_14_dialog_content = "O Rei Tritão... Ele não vai me deixar ir tão facilmente, vai?",
  ui_story_5066_50660702_15_dialog_content = "...",
  ui_story_5066_50660702_16_dialog_content = "Tsk, não se preocupe! Robyn e eu vamos proteger você!",
  ui_story_5066_50660702_17_dialog_content = "Isso mesmo... Afinal, você sempre foi tão gentil conosco.",
  ui_story_5066_50660702_18_dialog_content = "Pretendíamos retribuir você agora, mas você acabou nos salvando de novo...",
  ui_story_5066_50660702_19_dialog_content = "Mas... Mas eu estava apenas cumprindo meu dever.",
  ui_story_5066_50660702_20_dialog_content = "O Senhor Aqua me ajudou quando eu estava em perigo... Então eu tenho que retribuir realizando seus desejos...",
  ui_story_5066_50660702_21_dialog_content = "Afinal... Não me tirou nada quando formamos nosso pacto...",
  ui_story_5066_50660702_22_dialog_content = "Os desejos dele? Você quer dizer que vai ajudá-lo a retomar esta cidade?!",
  ui_story_5066_50660702_23_dialog_content = "Sim... Então, poderia me contar tudo o que sabe sobre o Rei Tritão?",
  ui_story_5066_50660702_24_dialog_content = "Claro! A Robyn é melhor em explicar essas coisas, então vou deixar ela fazer isso.",
  ui_story_5066_50660702_25_dialog_content = "Certo Dayna, mas você ainda precisa me ajudar a preencher as lacunas...",
  ui_story_5066_50660702_26_dialog_content = "Acho que devemos começar do começo mesmo.",
  ui_story_5066_50660702_27_dialog_content = "O Rei Tritão é... Um homem altivo que veio das Águas Rasas...",
  ui_story_5066_50660702_28_dialog_content = "E proclamou-se governante de todos os peixes.",
  ui_story_5066_50660702_29_dialog_content = "O cara é um fiel defensor da supremacia das Águas Rasas, então ele menospreza todas as outras raças que vivem no fundo do oceano.",
  ui_story_5066_50660702_30_dialog_content = "É por isso que ele recorre à crueldade e violência ao governar pequenas cidades como esta.",
  ui_story_5066_50660702_31_dialog_content = "É também por isso... Ele raramente se mostra por aqui.",
  ui_story_5066_50660702_32_dialog_content = "O Príncipe Tritão, por outro lado... É seu sucessor, bem como a pessoa que ele designou para coletar impostos de nós.",
  ui_story_5066_50660702_33_dialog_content = "Mesmo que o príncipe pareça um idiota...",
  ui_story_5066_50660702_34_dialog_content = "Não podemos esquecer que ele é uma pessoa ilustre do Raso, uma área rica em recursos e tecnologia avançada...",
  ui_story_5066_50660702_35_dialog_content = "Sua astúcia e armamento não devem ser subestimados.",
  ui_story_5066_50660702_36_dialog_content = "O que também significa que o Rei Tritão é ainda mais assustador.",
  ui_story_5066_50660702_37_dialog_content = "Você não acabou de dizer para não assustá-la...?",
  ui_story_5066_50660702_38_dialog_content = "Quer dizer, se vamos lutar, então realmente não há mais motivo para enrolar.",
  ui_story_5066_50660702_39_dialog_content = "Tadinha...",
  ui_story_5066_50660702_40_dialog_content = "Eu... Eu sou muito grato a ambos por me contarem tudo isso...",
  ui_story_5066_50660702_41_dialog_content = "Mas... Eu realmente tenho alguma chance contra alguém tão poderoso quanto o Rei Tritão?",
  ui_story_5066_50660702_42_dialog_content = "...",
  ui_story_5066_50660702_43_dialog_content = "Não tenha medo, Connolly. Você e o Aqua Lord são muito mais fortes do que todos eles...",
  ui_story_5066_50660702_44_dialog_content = "Não apenas isso, nós sempre estaremos ao seu lado...",
  ui_story_5066_50660702_45_dialog_content = "Isso mesmo! Vamos apenas esperar você se tornar o Queen!",
  ui_story_5066_50660702_46_dialog_content = "E quando esse dia chegar, serviremos como seus guardas reais!",
  ui_story_5066_50660702_47_dialog_content = "Um à sua esquerda... E um à sua direita.",
  ui_story_5066_50660702_48_dialog_content = "Nunca muito longe do seu lado...",
  ui_story_5066_50660702_49_dialog_content = "Assim, podemos te ajudar sempre que precisar, certo?",
  ui_story_5066_50660702_50_dialog_content = "Também estaríamos ajudando você a retomar o controle desta cidade!",
  ui_story_5066_50660702_51_dialog_content = "Você não pode me deixar de fora se for fazer algo legal assim!",
  ui_story_5066_50660702_52_dialog_content = "Além disso, eu estava querendo tirar aquele olhar arrogante do rosto do rei há algum tempo!",
  ui_story_5066_50660702_53_dialog_content = "A todos... Eu realmente não sei... Como eu poderia retribuir vocês...",
  ui_story_5066_50660702_54_dialog_content = "Mas com a sua ajuda, sei que não teria nada a temer.",
  ui_story_5066_50660702_55_dialog_content = "Então, por favor... Por favor, me empreste sua força...!",
  ui_story_5066_50660801_1_dialog_content = "*Tocando o clarinete*",
  ui_story_5066_50660801_2_dialog_content = "...",
  ui_story_5066_50660801_3_dialog_content = "Iiih! ... Mesmo não sendo minha primeira vez invocando, ainda não consigo evitar de sentir um pouco de medo...",
  ui_story_5066_50660801_4_dialog_content = "Hm... D-Desculpe por invocar você novamente tão cedo...",
  ui_story_5066_50660801_5_dialog_content = "Eu só queria te dizer... que estou pronto e disposto a realizar seus desejos.",
  ui_story_5066_50660801_6_dialog_content = "Estou profundamente satisfeito com sua decisão.",
  ui_story_5066_50660801_7_dialog_content = "Então, vamos tornar esse pacto oficial.",
  ui_story_5066_50660801_8_dialog_content = "Hã...? Mas eu pensei que já tínhamos formado nosso pacto?",
  ui_story_5066_50660801_9_dialog_content = "Eu sou o antigo... e grande Senhor Aqua. Um pacto temporário no campo de batalha é apenas uma medida de emergência.",
  ui_story_5066_50660801_10_dialog_content = "Não convém ao meu ilustre status.",
  ui_story_5066_50660801_11_dialog_content = "Ah... Tá. Então como devemos fazer isso...?",
  ui_story_5066_50660801_12_dialog_content = "Com seu clarinete como relíquia, vamos formalizar isso.",
  ui_story_5066_50660801_13_dialog_content = "Assim, eu posso sempre estar ao seu lado.",
  ui_story_5066_50660801_14_dialog_content = "Tá bom então, assim...?",
  ui_story_5066_50660801_15_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660801_16_dialog_content = "Muito bem, isso constitui o pacto oficial.",
  ui_story_5066_50660801_17_dialog_content = "Sendo o Queen, é seu dever administrar a cidade em meu nome.",
  ui_story_5066_50660801_18_dialog_content = "Ah... Vou fazer o meu melhor, mesmo nunca tendo feito algo assim antes...",
  ui_story_5066_50660801_19_dialog_content = "Além disso, reconstrua o templo.",
  ui_story_5066_50660801_20_dialog_content = "Para restaurar meu poder e me defender do ataque iminente do Rei Tritão.",
  ui_story_5066_50660801_21_dialog_content = "Uh... Que templo?",
  ui_story_5066_50660801_22_dialog_content = "Eu mencionei isso antes, mas você... não interpretou.",
  ui_story_5066_50660801_23_dialog_content = "Não sei como dizer isso... parece que vamos fazer todos trabalharem.",
  ui_story_5066_50660801_24_dialog_content = "Mas... Eu prometo que vou pensar em alguma coisa...",
  ui_story_5066_50660801_25_dialog_content = "Então, uh... Que tipo de templo você quer?",
  ui_story_5066_50660801_26_dialog_content = "Para me honrar, o grande Senhor Aqua, há requisitos sobre a escala do meu templo, que você deve ter em mente.",
  ui_story_5066_50660801_27_dialog_content = "E-Entendi!",
  ui_story_5066_50660801_28_dialog_content = "Em primeiro lugar, deve ser tão grandioso quanto a igreja onde reside o demônio noturno.",
  ui_story_5066_50660801_29_dialog_content = "O \"demônio noturno\"? Hmm... Um grande templo... Uh-huh, entendi.",
  ui_story_5066_50660801_30_dialog_content = "Deve ser tão misterioso quanto a Casa da Bruxa...",
  ui_story_5066_50660801_31_dialog_content = "\"Tão misterioso quanto a casa de uma bruxa...\"",
  ui_story_5066_50660801_32_dialog_content = "Sim, isso deve se encaixar muito bem!",
  ui_story_5066_50660801_33_dialog_content = "Deve possuir o charme antigo de um castelo herético.",
  ui_story_5066_50660801_34_dialog_content = "Um castelo antigo? Você tem bom gosto em arquitetura, Aqua Lord...",
  ui_story_5066_50660801_35_dialog_content = "Deve brilhar no escuro como um Trapézio Reluzente.",
  ui_story_5066_50660801_36_dialog_content = "Um templo que brilha no escuro... Parece algo saído de um conto de fadas, mas eu meio que gosto disso...",
  ui_story_5066_50660801_37_dialog_content = "Isso deve ser tudo... Você entendeu completamente?",
  ui_story_5066_50660801_38_dialog_content = "Eu achei que seria muito mais complicado do que isso... Mas não é tão difícil de entender!",
  ui_story_5066_50660801_39_dialog_content = "Então, uh... Você quer um grande, antigo, mágico e brilhante castelo, certo?",
  ui_story_5066_50660801_40_dialog_content = "...?",
  ui_story_5066_50660801_41_dialog_content = "Não tenho muita experiência com essas coisas... Mas, por favor, acredite em mim...",
  ui_story_5066_50660801_42_dialog_content = "E eu te prometo... Vou construir um templo do qual você possa se orgulhar!",
  ui_story_5066_50660801_43_dialog_content = "Espero que você possa cumprir a promessa.",
  ui_story_5066_50660801_44_dialog_content = "Tá bom...",
  ui_story_5066_50660801_45_dialog_content = "O que há de errado, Connolly?",
  ui_story_5066_50660801_46_dialog_content = "Você acabou de formar um pacto oficial com o Senhor da Água... Mas parece que você não está muito feliz?",
  ui_story_5066_50660801_47_dialog_content = "Bem, isso realmente me deu uma missão muito difícil...",
  ui_story_5066_50660801_48_dialog_content = "Gerenciar uma cidade, construir um templo... Eu nunca fiz nada disso antes...",
  ui_story_5066_50660801_49_dialog_content = "Não há motivo para preocupação! Você só não tentou ainda, só isso!",
  ui_story_5066_50660801_50_dialog_content = "Uma vez que você tentar, vai descobrir que não é tão difícil quanto pensava. Você sempre teve esse tipo de talento.",
  ui_story_5066_50660801_51_dialog_content = "Não só isso... Nós e os moradores da cidade vamos ajudá-lo da melhor forma possível...",
  ui_story_5066_50660801_52_dialog_content = "Se isso significa nos livrar do domínio do Rei Tritão... Tenho certeza de que todos estarão animados para ajudar.",
  ui_story_5066_50660801_53_dialog_content = "Isso mesmo, e tudo que você precisa fazer é atender às expectativas deles.",
  ui_story_5066_50660801_54_dialog_content = "R... Sério?",
  ui_story_5066_50660801_55_dialog_content = "Então... também vou tentar com tudo o que eu tenho...",
  ui_story_5066_50660801_56_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5066_50660801_57_dialog_content = "Vossa Majestade, imploro seu perdão!",
  ui_story_5066_50660801_58_dialog_content = "Meu perdão? Meu filho foi submetido a tanta crueldade, e...",
  ui_story_5066_50660801_59_dialog_content = "Aquele que o atacou; era seu primo, não era?",
  ui_story_5066_50660801_60_dialog_content = "Bem... isso é apenas um estranho que nossa família adotou, basicamente... não somos parentes!",
  ui_story_5066_50660801_61_dialog_content = "Bem, se é esse o caso, você também não tem valor para mim. Guardas...",
  ui_story_5066_50660801_62_dialog_content = "Espere! Eu sei a fraqueza dela... Se você for à guerra, eu posso garantir sua vitória!",
  ui_story_5066_50660801_63_dialog_content = "...?",
  ui_story_5066_50660801_64_dialog_content = "Continue, estou ouvindo.",
  ui_story_5066_50660801_65_dialog_content = "Ela é... apenas uma garota comum. É o poder da clarineta que a torna tão formidável.",
  ui_story_5066_50660801_66_dialog_content = "Eu... Eu, como primo dela, posso te ajudar a roubar o clarinete!",
  ui_story_5066_50660801_67_dialog_content = "Então, os moradores da cidade não seriam nada mais do que um grupo desorganizado à sua mercê.",
  ui_story_5066_50660801_68_dialog_content = "Você está falando a verdade?",
  ui_story_5066_50660801_69_dialog_content = "Absolutamente verdade, Vossa Majestade.",
  ui_story_5066_50660801_70_dialog_content = "Muito bem, vou te dar uma chance de fazer isso, mas se não der certo...",
  ui_story_5066_50660801_71_dialog_content = "Estou disposto a aceitar a punição!",
  ui_story_5066_50660901_1_dialog_content = "Ufa... finalmente terminei o trabalho de hoje...",
  ui_story_5066_50660901_2_dialog_content = "Lidar com todos os problemas das pessoas... Já era o suficiente para fazer minha cabeça girar...",
  ui_story_5066_50660901_3_dialog_content = "Nããão... Como vou construir um templo em cima de tudo isso...?",
  ui_story_5066_50660901_4_dialog_content = "Sinto falta do meu sótão... E da minha música...",
  ui_story_5066_50660901_5_dialog_content = "Ótimo trabalho hoje, Connolly!",
  ui_story_5066_50660901_6_dialog_content = "Você também, Dayna...",
  ui_story_5066_50660901_7_dialog_content = "Sem você e Robyn... Eu não sei o que eu faria...",
  ui_story_5066_50660901_8_dialog_content = "Não seja tão humilde... Na minha opinião, você está fazendo um trabalho fantástico como mensageiro do Senhor Aqua.",
  ui_story_5066_50660901_9_dialog_content = "Hã... M-Mesmo...?",
  ui_story_5066_50660901_10_dialog_content = "Mas se vocês dois não estivessem aqui... Eu nem teria coragem de conversar com os moradores da cidade...",
  ui_story_5066_50660901_11_dialog_content = "Tudo bem. Afinal, todos somos bons em coisas diferentes.",
  ui_story_5066_50660901_12_dialog_content = "E nós vamos ajudá-lo... com as coisas que você não é bom...",
  ui_story_5066_50660901_13_dialog_content = "Especialmente a luta! Deixe isso conosco!",
  ui_story_5066_50660901_14_dialog_content = "Entendo... Obrigado a ambos por me incentivarem...",
  ui_story_5066_50660901_15_dialog_content = "Então, se não houver mais nada para hoje, vamos embora agora.",
  ui_story_5066_50660901_16_dialog_content = "Descanse bastante, Connolly... Afinal, amanhã... também deve ser bem agitado...",
  ui_story_5066_50660901_17_dialog_content = "Uh-huh... Farei.",
  ui_story_5066_50660901_18_dialog_content = "...",
  ui_story_5066_50660901_19_dialog_content = "*atordoado* Hmm...",
  ui_story_5066_50660901_20_dialog_content = "...",
  ui_story_5066_50660901_21_dialog_content = "Ah...! L-Lorde Aqua...?",
  ui_story_5066_50660901_22_dialog_content = "Por favor, não apareça atrás de mim tão de repente... Você realmente me assustou...",
  ui_story_5066_50660901_23_dialog_content = "Estou apenas preocupado com o progresso da construção do meu templo.",
  ui_story_5066_50660901_24_dialog_content = "Ah... Uh... Sobre isso...",
  ui_story_5066_50660901_25_dialog_content = "Não entendo...",
  ui_story_5066_50660901_26_dialog_content = "Hã? O que você quer dizer...?",
  ui_story_5066_50660901_27_dialog_content = "Você já possui um poder absoluto e formidável.",
  ui_story_5066_50660901_28_dialog_content = "Basta usar seu poder para fazer com que esses habitantes subaquáticos construam meu templo e afastem o inimigo para você.",
  ui_story_5066_50660901_29_dialog_content = "Então, por que você se preocupa tanto com as vidas deles?",
  ui_story_5066_50660901_30_dialog_content = "Hum... Era assim que você costumava governar o povo submarino, Senhor Aqua?",
  ui_story_5066_50660901_31_dialog_content = "Há algo de errado com isso?",
  ui_story_5066_50660901_32_dialog_content = "Bem, essas pessoas... Todas elas têm seus próprios pensamentos e emoções. São seres vivos, não ferramentas...",
  ui_story_5066_50660901_33_dialog_content = "A razão pela qual eles estão tão insatisfeitos com o Rei Tritão agora é porque ele também os trata como mercadorias descartáveis...",
  ui_story_5066_50660901_34_dialog_content = "Se tratarmos eles exatamente da mesma maneira... Eles não nos apoiarão da mesma forma que estão nos apoiando agora.",
  ui_story_5066_50660901_35_dialog_content = "...",
  ui_story_5066_50660901_36_dialog_content = "Hum... Você... entende o que estou tentando dizer?",
  ui_story_5066_50660901_37_dialog_content = "Acredito no poder absoluto, e suas palavras não podem me convencer...",
  ui_story_5066_50660901_38_dialog_content = "Ah... Então como devo explicar...?",
  ui_story_5066_50660901_39_dialog_content = "Ah... Entendi...",
  ui_story_5066_50660901_40_dialog_content = "Nós costumávamos nos comunicar através deste clarinete antes... Certo?",
  ui_story_5066_50660901_41_dialog_content = "Então, deixe-me tocar uma música chamada \"Casa\" para você.",
  ui_story_5066_50660901_42_dialog_content = "É minha música favorita. Minha mãe me ensinou há muito tempo...",
  ui_story_5066_50660901_43_dialog_content = "Espero que isso permita que você entenda meus pensamentos um pouco mais claramente...",
  ui_story_5066_50660901_44_dialog_content = "Estou... ansioso por isso.",
  ui_story_5066_50660901_45_dialog_content = "Tudo bem, estou pronto...",
  ui_story_5066_50660901_46_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660901_47_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660901_48_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660901_49_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50660901_50_dialog_content = "Ahh... A música da mamãe sempre me acalma mais...",
  ui_story_5066_50660901_51_dialog_content = "...",
  ui_story_5066_50660901_52_dialog_content = "Ah... Desculpe, acho que... me empolguei demais.",
  ui_story_5066_50660901_53_dialog_content = "Tudo bem... Estou profundamente emocionado.",
  ui_story_5066_50660901_54_dialog_content = "Entendi. Você não vê essa cidade subaquática como um lugar para governar, mas sim como... seu lar.",
  ui_story_5066_50660901_55_dialog_content = "Apesar de enfrentar hostilidade, você não guarda ressentimento, pois você, que perdeu seus pais, encontrou um lugar ao qual pertencer.",
  ui_story_5066_50660901_56_dialog_content = "Você não está lutando pelos seus desejos; você está lutando para proteger a cidade que lhe oferece abrigo.",
  ui_story_5066_50660901_57_dialog_content = "Oh... Não é realmente nada de especial...",
  ui_story_5066_50660901_58_dialog_content = "Eu só... Eu só acho que seria bom se todos pudessem viver felizes em um lugar que possam chamar de seu, só isso...",
  ui_story_5066_50660901_59_dialog_content = "Todos estão trabalhando duro para construir seu templo, então... espero que também se sinta em casa para você!",
  ui_story_5066_50660901_60_dialog_content = "...",
  ui_story_5066_50660901_61_dialog_content = "Talvez formar um pacto com você seja a escolha mais correta que fiz ao longo dos meus longos anos.",
  ui_story_5066_50660901_62_dialog_content = "Estarei esperando com grande expectativa pelo... lar que você vai proporcionar para mim.",
  ui_story_5066_50660901_63_dialog_content = "Ufa...",
  ui_story_5066_50660901_64_dialog_content = "Ajudar todo mundo a resolver seus problemas me faz sentir feliz e tudo mais...",
  ui_story_5066_50660901_65_dialog_content = "Mas ainda prefiro aproveitar meu tempo sozinho à noite.",
  ui_story_5066_50660901_66_dialog_content = "...",
  ui_story_5066_50660901_67_dialog_content = "Hã? É tão tarde... Quem poderia estar me procurando a essa hora...?",
  ui_story_5066_50660901_68_dialog_content = "Humm... Talvez eu deva fingir estar dormindo...",
  ui_story_5066_50660901_69_dialog_content = "Não, eu me sentiria mal se fizesse isso. Vou dar uma olhada...",
  ui_story_5066_50660901_70_dialog_content = "<color=#e8d9bb>Wham—</color>",
  ui_story_5066_50660901_71_dialog_content = "E-Ei! Não precisa ser rude... Já estou a caminho!",
  ui_story_5066_50660901_72_dialog_content = "...",
  ui_story_5066_50660901_73_dialog_content = "Quem é você...? E como entrou aqui...?",
  ui_story_5066_50660901_74_dialog_content = "Hã?! O que está acontecendo...? Por que você... está segurando meu clarinete nas mãos?!",
  ui_story_5066_50660901_75_dialog_content = "Tsk, fui pego tão cedo...",
  ui_story_5066_50660901_76_dialog_content = "Como um morador dedicado da cidade, estou fazendo isso para o seu próprio bem, Queen Connolly!",
  ui_story_5066_50660901_77_dialog_content = "Você consegue falar com aquele monstro por causa dessa coisa, né?",
  ui_story_5066_50660901_78_dialog_content = "Não é apenas uma coisa... É-Esta é uma herança da minha mãe! É importante para mim!",
  ui_story_5066_50660901_79_dialog_content = "Eu não me importo se é uma relíquia ou não; se deixarmos você agir assim, a cidade inteira pagará o preço!",
  ui_story_5066_50660901_80_dialog_content = "No entanto, se eu apresentar isso ao Rei Tritão, você e seus seguidores não poderão causar problemas. Heh-heh...",
  ui_story_5066_50660901_81_dialog_content = "Preparem-se para o exército do Rei Tritão esmagar esta tola cidade!",
  ui_story_5066_50660901_82_dialog_content = "E-Espere...!",
  ui_story_5066_50660901_83_dialog_content = "Por favor... Por favor, me devolva!",
  ui_story_5066_50660901_84_dialog_content = "Tsk, você simplesmente não desiste, né?",
  ui_story_5066_50660901_85_dialog_content = "Hee-hee, já estou preparado para isso!",
  ui_story_5066_50660901_86_dialog_content = "...",
  ui_story_5066_50660901_87_dialog_content = "Eeee!",
  ui_story_5066_50660901_88_dialog_content = "Eu não quero problemas, então por favor... por favor saia do meu caminho...!",
  ui_story_5066_50660901_89_dialog_content = "...!",
  ui_story_5066_50660901_90_dialog_content = "Ah... Não tenho escolha a não ser lutar, mas eu juro... Eu juro que vou alcançar aquele ladrão...",
  ui_story_5066_50660902_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5066_50660902_2_dialog_content = "Mesmo assim... eu consegui despistar aqueles guardas...",
  ui_story_5066_50660902_3_dialog_content = "Parece que... o ladrão... já foi embora há muito tempo...",
  ui_story_5066_50660902_4_dialog_content = "Aqua Lord... Você... ainda está aí...?",
  ui_story_5066_50660902_5_dialog_content = "...",
  ui_story_5066_50660902_6_dialog_content = "Boo-hoo... Eu sabia. Sem o clarinete, não podemos nos comunicar um com o outro.",
  ui_story_5066_50660902_7_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50660902_8_dialog_content = "Huh? ... O-O que foi esse barulho? Não me diga...",
  ui_story_5066_50660902_9_dialog_content = "O rei e o ladrão estão trabalhando juntos para nos atacar em todas as frentes...?",
  ui_story_5066_50660902_10_dialog_content = "Eu... Eu talvez não consiga mais alcançar o Aqua Lord, mas...",
  ui_story_5066_50660902_11_dialog_content = "Prometi que não recuaria...",
  ui_story_5066_50660902_12_dialog_content = "Majestade, é isso!",
  ui_story_5066_50660902_13_dialog_content = "...",
  ui_story_5066_50660902_14_dialog_content = "Eu nunca esperava que uma rebelião acontecesse em uma cidade tão decadente.",
  ui_story_5066_50660902_15_dialog_content = "Vou mostrar a esses rebeldes o quão tolos eles são!",
  ui_story_5066_50660902_16_dialog_content = "Agora nomeio vocês como vanguardas! Sigam-me e mostrem juntos o poder e a majestade do nosso Reino dos Tritões!",
  ui_story_5066_50660902_17_dialog_content = "Sim!!!",
  ui_story_5066_50660902_18_dialog_content = "...",
  ui_story_5066_50660902_19_dialog_content = "É aquele... o Rei Tritão?!",
  ui_story_5066_50660902_20_dialog_content = "Ele está realmente aqui... para buscar vingança por seu filho...?",
  ui_story_5066_50660902_21_dialog_content = "Rápido! Vá e informe Queen Connolly!",
  ui_story_5066_50660902_22_dialog_content = "Heh, que bando de pessoas desorganizadas.",
  ui_story_5066_50660902_23_dialog_content = "Todos vocês, humildes moradores, olhem bem! Eu sou o seu rei!",
  ui_story_5066_50660902_24_dialog_content = "Agora, oficialmente proclamo Connolly e seus seguidores como rebeldes.",
  ui_story_5066_50660902_25_dialog_content = "Aqui, busco vingança pela humilhação que meu filho sofreu e pela rebelião dos moradores da cidade!",
  ui_story_5066_50660902_26_dialog_content = "Guardas, preparem-se para a batalha!",
  ui_story_5066_50660902_27_dialog_content = "Sim!!!",
  ui_story_5066_50661001_1_dialog_content = "...",
  ui_story_5066_50661001_2_dialog_content = "Rei Tritão... mesmo que você costumava nos oprimir, agora, não temos mais medo de você!",
  ui_story_5066_50661001_3_dialog_content = "Com a proteção de Queen Connolly, você não representa ameaça alguma para nós!",
  ui_story_5066_50661001_4_dialog_content = "Hahahaha, Queen Connolly? Que nome ridículo!",
  ui_story_5066_50661001_5_dialog_content = "Você pode não ter medo de mim, mas estou curioso para ver se tem medo disso!",
  ui_story_5066_50661001_6_dialog_content = "Isso é... um canhão?",
  ui_story_5066_50661001_7_dialog_content = "O barril é tão grande... mas para Queen Connolly, não é grande coisa!",
  ui_story_5066_50661001_8_dialog_content = "Sim, pessoal, não tenham medo; esperem pelo Queen Connolly para lidar com isso!",
  ui_story_5066_50661001_9_dialog_content = "Huff... Huff... Huff...",
  ui_story_5066_50661001_10_dialog_content = "Ah... Desculpe, me atrasei...",
  ui_story_5066_50661001_11_dialog_content = "Queen Connolly está aqui!",
  ui_story_5066_50661001_12_dialog_content = "Assim como você mandou aquele príncipe irritante voar, derrube também este rei arrogante!",
  ui_story_5066_50661001_13_dialog_content = "Mande-o voar! Mande-o voar! Mande-o voar!",
  ui_story_5066_50661001_14_dialog_content = "Tá bom...",
  ui_story_5066_50661001_15_dialog_content = "Esses tentáculos ainda estão comigo...",
  ui_story_5066_50661001_16_dialog_content = "Mas...",
  ui_story_5066_50661001_17_dialog_content = "Esta é a rainha que todos vocês estavam esperando? Realmente uma visão, devo dizer!",
  ui_story_5066_50661001_18_dialog_content = "Preparem-se, vanguardas! Fogo!",
  ui_story_5066_50661001_19_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661001_20_dialog_content = "Urgh... Eu... Eu vou proteger todos!",
  ui_story_5066_50661001_21_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5066_50661001_22_dialog_content = "Ah, não assim... Os tentáculos não estão seguindo minhas ordens...",
  ui_story_5066_50661001_23_dialog_content = "Não, espera... não é que eles não acompanham. Eles simplesmente não conseguem me entender...",
  ui_story_5066_50661001_24_dialog_content = "Neste ritmo...",
  ui_story_5066_50661001_25_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661001_26_dialog_content = "Eh... será que o poder de Queen Connolly não pode competir com os canhões e vanguardas do rei?",
  ui_story_5066_50661001_27_dialog_content = "Ela parece um pouco estranha. Será que vamos perder...?",
  ui_story_5066_50661001_28_dialog_content = "Pare com esse tipo de conversa! Não há como perdermos!",
  ui_story_5066_50661001_29_dialog_content = "Em uma situação como essa... Devemos ajudá-la a recuperar sua força anterior...",
  ui_story_5066_50661001_30_dialog_content = "Isso mesmo, então vamos dar a ela toda a cobertura que ela precisa!",
  ui_story_5066_50661001_31_dialog_content = "Pessoal... Mas eu...",
  ui_story_5066_50661001_32_dialog_content = "Sem o meu clarinete... Eu não sou nem de longe tão forte quanto costumava ser...",
  ui_story_5066_50661001_33_dialog_content = "Mas esses tentáculos... E-Enquanto eles ainda estiverem aqui, eu vou continuar lutando...!",
  ui_story_5066_50661102_1_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661102_2_dialog_content = "Ugh...",
  ui_story_5066_50661102_3_dialog_content = "Connolly! Você está bem?!",
  ui_story_5066_50661102_4_dialog_content = "Eu... estou bem, é só que...",
  ui_story_5066_50661102_5_dialog_content = "O Aqua Lord... Acho que ele não vai aguentar por muito mais tempo...",
  ui_story_5066_50661102_6_dialog_content = "<anim type=Shake>éµè Œâ...</anim>",
  ui_story_5066_50661102_7_dialog_content = "<anim type=Shake>ç·tu€¦... ï|'H>■</anim>",
  ui_story_5066_50661102_8_dialog_content = "Desculpe muito... Mas agora... Eu não consigo entender uma palavra do que você está dizendo...",
  ui_story_5066_50661102_9_dialog_content = "<anim type=Shake>ç·tuوˆگم€... â€¦â€■</anim>",
  ui_story_5066_50661102_10_dialog_content = "Ei... olhe para Queen Connolly! Ela...",
  ui_story_5066_50661102_11_dialog_content = "Aqueles tentáculos... Eles estão desaparecendo, sumindo...",
  ui_story_5066_50661102_12_dialog_content = "<size=45>Hahahahaha!</size>",
  ui_story_5066_50661102_13_dialog_content = "A suposta nova rainha de vocês não passa de uma testa de ferro!",
  ui_story_5066_50661102_14_dialog_content = "Todos, avancem! Quem conseguir capturá-la será ricamente recompensado!",
  ui_story_5066_50661102_15_dialog_content = "Espere aí! Seu oponente está aqui!",
  ui_story_5066_50661102_16_dialog_content = "Nós não vamos... deixar você chegar perto de Connolly...",
  ui_story_5066_50661102_17_dialog_content = "Ridículo! Você acredita que pode me parar?",
  ui_story_5066_50661102_18_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661102_19_dialog_content = "Argh! Saia do meu caminho, seus capachos sujos!",
  ui_story_5066_50661102_20_dialog_content = "Deixe esses caras comigo, Dayna. Vá rápido até Connolly...",
  ui_story_5066_50661102_21_dialog_content = "Sim!",
  ui_story_5066_50661102_22_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661102_23_dialog_content = "<size=33>Boo-hoo... Não, eu estraguei tudo de novo... Eu... Eu sinto muito!</size>",
  ui_story_5066_50661102_24_dialog_content = "Aguente firme, Connolly!",
  ui_story_5066_50661102_25_dialog_content = "É... É você, Dayna?",
  ui_story_5066_50661102_26_dialog_content = "Sim! Não se preocupe, vou cobrir sua fuga.",
  ui_story_5066_50661102_27_dialog_content = "Huh...? Mas eu não posso simplesmente deixar todo mundo para trás assim...",
  ui_story_5066_50661102_28_dialog_content = "Tudo bem, então apenas deixe isso conosco por enquanto.",
  ui_story_5066_50661102_29_dialog_content = "É verdade que não sabemos realmente como ajudá-lo agora.",
  ui_story_5066_50661102_30_dialog_content = "Mas você vai voltar assim que recuperar suas forças, certo?",
  ui_story_5066_50661102_31_dialog_content = "Eu...",
  ui_story_5066_50661102_32_dialog_content = "Conversamos mais tarde, agora vá!",
  ui_story_5066_50661102_33_dialog_content = "Boo-hoo... Vou fazer o que você mandou.",
  ui_story_5066_50661102_34_dialog_content = "<size=33><color=#e8d9bb>Estrondo—!</color></size>",
  ui_story_5066_50661102_35_dialog_content = "Eles ainda estão lutando...",
  ui_story_5066_50661102_36_dialog_content = "É tudo tão assustador... Snif... Eu realmente estou melhor em um lugar escuro como este.",
  ui_story_5066_50661102_37_dialog_content = "Enquanto eu me esconder nesta trincheira escura e vazia, tudo ficará bem...",
  ui_story_5066_50661102_38_dialog_content = "Tudo vai ficar bem... Certo?",
  ui_story_5066_50661102_39_dialog_content = "Finalmente... Posso ter um sono decente... Certo?",
  ui_story_5066_50661201_1_dialog_content = "<size=45><color=#e8d9bb>Estrondo—!</color></size>",
  ui_story_5066_50661201_2_dialog_content = "Tadinha...",
  ui_story_5066_50661201_3_dialog_content = "Eu... eu deveria estar ajudando os outros...",
  ui_story_5066_50661201_4_dialog_content = "Mas meu corpo... Não para de tremer...",
  ui_story_5066_50661201_5_dialog_content = "Afinal, não consigo controlar esses tentáculos... Não como estou agora...",
  ui_story_5066_50661201_6_dialog_content = "Mesmo que eu voltasse, só atrapalharia todo mundo...",
  ui_story_5066_50661201_7_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5066_50661201_8_dialog_content = "Nossa... Tão quente... Será que é uma corrente de água quente?",
  ui_story_5066_50661201_9_dialog_content = "<color=#e8d9bb>Pat—</color>",
  ui_story_5066_50661201_10_dialog_content = "Hmm? Meu ombro...?",
  ui_story_5066_50661201_11_dialog_content = "Iiiihh! A-Alguém me encontrou...? Mas, seja quem for, não parecem hostis...",
  ui_story_5066_50661201_12_dialog_content = "Quem... Quem poderia ter me encontrado aqui e agora, de todos os lugares...?",
  ui_story_5066_50661201_13_dialog_content = "Olá, Connolly.",
  ui_story_5066_50661201_14_dialog_content = "Uau... Que golfinho branco lindo! E os olhos dele... São tão calorosos e brilhantes...",
  ui_story_5066_50661201_15_dialog_content = "Quem é você?",
  ui_story_5066_50661201_16_dialog_content = "Não precisa ter medo, Connolly. Eu sou um dos habitantes do fundo do mar que você e o Senhor Aqua ajudaram.",
  ui_story_5066_50661201_17_dialog_content = "Ah... Sério? Mas eu não consigo me lembrar...",
  ui_story_5066_50661201_18_dialog_content = "Entendo. Com tantos que você ajudou, é impossível lembrar de todos eles.",
  ui_story_5066_50661201_19_dialog_content = "Eu sei... mas ainda assim...",
  ui_story_5066_50661201_20_dialog_content = "<size=33>Não acho que eu poderia esquecer um golfinho branco tão gentil e bonito tão facilmente...</size>",
  ui_story_5066_50661201_21_dialog_content = "Mas parece que você se meteu em um pouco de problema agora.",
  ui_story_5066_50661201_22_dialog_content = "E agora é a minha vez de ajudá-lo o máximo que eu puder.",
  ui_story_5066_50661201_23_dialog_content = "Eu... boo-hoo... Você está absolutamente certo...",
  ui_story_5066_50661201_24_dialog_content = "Mas como eu poderia... possivelmente incomodá-lo com meus problemas?",
  ui_story_5066_50661201_25_dialog_content = "Por que seria um incômodo? Inspirado por você e como você tem prazer em ajudar os outros, agora reuni coragem para dar uma mão.",
  ui_story_5066_50661201_26_dialog_content = "Além disso, o mundo subaquático é nosso lar compartilhado, então gostaria de fazer minha parte para protegê-lo.",
  ui_story_5066_50661201_27_dialog_content = "Oh... É mesmo...?",
  ui_story_5066_50661201_28_dialog_content = "Bem, primeiro, precisamos sair daqui.",
  ui_story_5066_50661201_29_dialog_content = "Este lugar não é adequado para você no seu estado atual.",
  ui_story_5066_50661201_30_dialog_content = "Eu... eu sei, mas para onde devo ir agora?",
  ui_story_5066_50661201_31_dialog_content = "Conheço um refúgio seguro. Gostaria de vir comigo?",
  ui_story_5066_50661201_32_dialog_content = "Sim... Se você não se importar...",
  ui_story_5066_50661201_33_dialog_content = "Por favor... me leve com você...",
  ui_story_5066_50661201_34_dialog_content = "... Espere.",
  ui_story_5066_50661201_35_dialog_content = "O que houve?",
  ui_story_5066_50661201_36_dialog_content = "Vai ter outras pessoas lá também...?",
  ui_story_5066_50661201_37_dialog_content = "Sim, é claro. Afinal, todos gostam bastante daquele lugar.",
  ui_story_5066_50661201_38_dialog_content = "Ai...",
  ui_story_5066_50661201_39_dialog_content = "Dayna e os outros ainda estão lutando...",
  ui_story_5066_50661201_40_dialog_content = "Mas eu... eu não sei como devo ajudá-los...",
  ui_story_5066_50661201_41_dialog_content = "As pessoas lá... não ficarão ressentidas comigo por isso?",
  ui_story_5066_50661201_42_dialog_content = "Não precisa se preocupar demais.",
  ui_story_5066_50661201_43_dialog_content = "Talvez você possa se sentir mais confiante com a reputação que construiu ao ajudar os moradores no passado.",
  ui_story_5066_50661201_44_dialog_content = "Mais... confiante?",
  ui_story_5066_50661201_45_dialog_content = "Mas eu não sou mais a rainha em quem confiavam... Agora sou apenas uma fugitiva vergonhosa...",
  ui_story_5066_50661201_46_dialog_content = "Ainda não é tarde demais.",
  ui_story_5066_50661201_47_dialog_content = "Você está apenas dando um passo atrás por enquanto, e todo mundo se identifica totalmente com isso.",
  ui_story_5066_50661201_48_dialog_content = "Você não estava sempre ajudando-os no passado, tratando dos assuntos dos moradores subaquáticos como se fossem seus próprios?",
  ui_story_5066_50661201_49_dialog_content = "Agora é sua vez de buscar a ajuda deles.",
  ui_story_5066_50661201_50_dialog_content = "Será que... eu realmente sou digno de fazer isso?",
  ui_story_5066_50661201_51_dialog_content = "Claro, é por causa da sua bondade que Dayna, Robyn e todos os outros se reúnem ao seu redor.",
  ui_story_5066_50661201_52_dialog_content = "A sabedoria deles certamente será útil para resolver seus problemas.",
  ui_story_5066_50661201_53_dialog_content = "O conhecimento combinado de todos... realmente parece ser assim...",
  ui_story_5066_50661201_54_dialog_content = "Mesmo que eu não saiba o que fazer, talvez um deles... tenha a resposta?",
  ui_story_5066_50661201_55_dialog_content = "Tenha fé em todos e em si mesmo.",
  ui_story_5066_50661201_56_dialog_content = "Tudo o que você fez antes disso não será em vão.",
  ui_story_5066_50661201_57_dialog_content = "Não se esqueça, você ainda precisa cumprir o desejo do antigo monstro, certo?",
  ui_story_5066_50661201_58_dialog_content = "Ah!",
  ui_story_5066_50661201_59_dialog_content = "É verdade... Senhor Aqua... Sinto muito por envergonhá-lo assim...",
  ui_story_5066_50661201_60_dialog_content = "Mas agora eu sei... Preciso pedir a opinião de todos!",
  ui_story_5066_50661301_1_dialog_content = "<color=#e8d9bb>Tinir, tinir, tinir—</color>",
  ui_story_5066_50661301_2_dialog_content = "Uau... Eu não fazia ideia de que um lugar assim existia aqui embaixo...",
  ui_story_5066_50661301_3_dialog_content = "Está tão quente e tranquilo... Parece que estou em casa.",
  ui_story_5066_50661301_4_dialog_content = "Este lugar é bem encantador, não é?",
  ui_story_5066_50661301_5_dialog_content = "É sim. Muito obrigado por me trazer aqui...",
  ui_story_5066_50661301_6_dialog_content = "Ah... Ai não! Eu quase quis ficar aqui e evitar meus problemas...",
  ui_story_5066_50661301_7_dialog_content = "Mesmo sendo tão agradável... eu sei que não posso me esconder aqui para sempre.",
  ui_story_5066_50661301_8_dialog_content = "Então, você já descobriu qual problema quer pedir ajuda a todos?",
  ui_story_5066_50661301_9_dialog_content = "Ah... Eu acabei de perceber... na verdade, tem tanta gente aqui...",
  ui_story_5066_50661301_10_dialog_content = "Ei, isso não é Connolly?",
  ui_story_5066_50661301_11_dialog_content = "Recuperamos o recife de corais da nossa família dos Tritões, tudo graças a você!",
  ui_story_5066_50661301_12_dialog_content = "Nossas crianças adoram você! Quando é conveniente para você dar outra aula de música para eles?",
  ui_story_5066_50661301_13_dialog_content = "É assim mesmo... que todos me veem...?",
  ui_story_5066_50661301_14_dialog_content = "De fato, a bondade aproxima as pessoas.",
  ui_story_5066_50661301_15_dialog_content = "Então é por isso que eu deveria... confiar nas boas intenções de todos também...",
  ui_story_5066_50661301_16_dialog_content = "Eu... Eu entendi agora!",
  ui_story_5066_50661301_17_dialog_content = "Hum... Posso incomodar todos vocês por apenas alguns minutos do seu tempo?",
  ui_story_5066_50661301_18_dialog_content = "Vá em frente. Podemos perceber que você parece ter encontrado alguns problemas.",
  ui_story_5066_50661301_19_dialog_content = "Se houver algo em que possamos ajudar, não hesite em nos dizer!",
  ui_story_5066_50661301_20_dialog_content = "E se tem mais...",
  ui_story_5066_50661301_21_dialog_content = "Boo-hoo, eu não percebi que todos estariam tão dispostos a ajudar...",
  ui_story_5066_50661301_22_dialog_content = "Ahem. Bem, pessoal, eu realmente aprecio o entusiasmo de vocês.",
  ui_story_5066_50661301_23_dialog_content = "Mas por favor, um de cada vez, senão Connolly não conseguirá ouvir ninguém.",
  ui_story_5066_50661301_24_dialog_content = "Ah... Valeu, Golfinho Branco.",
  ui_story_5066_50661301_25_dialog_content = "<size=33>Sem você... Eu não sei o que eu faria...</size>",
  ui_story_5066_50661301_26_dialog_content = "Eu... Hm, gostaria de pedir a opinião de todos sobre um determinado assunto...",
  ui_story_5066_50661301_27_dialog_content = "Há algum tempo atrás... Um ladrão malvado roubou meu clarinete e, assim, perdi minha habilidade de me comunicar com o Senhor da Água...",
  ui_story_5066_50661301_28_dialog_content = "Alguém tem alguma ideia... de como posso restabelecer minha conexão com o Senhor da Água?",
  ui_story_5066_50661301_29_dialog_content = "...",
  ui_story_5066_50661301_30_dialog_content = "E-Eu tenho uma sugestão!",
  ui_story_5066_50661301_31_dialog_content = "Por favor, vá em frente.",
  ui_story_5066_50661301_32_dialog_content = "Nas histórias lendárias que ouvi quando era jovem, o poder do Senhor da Água está intimamente ligado ao templo!",
  ui_story_5066_50661301_33_dialog_content = "Isso tem que ser uma pista crucial! Além disso, Connolly, você não mencionou o templo mais cedo?",
  ui_story_5066_50661301_34_dialog_content = "Se você conseguir encontrar este templo antigo, com certeza recuperará seu poder!",
  ui_story_5066_50661301_35_dialog_content = "Connolly, qual é a sua opinião sobre isso?",
  ui_story_5066_50661301_36_dialog_content = "Acho que... Você tem razão...",
  ui_story_5066_50661301_37_dialog_content = "Mas eu posso voltar muito tarde se eu for procurar o templo antigo agora. Além disso...",
  ui_story_5066_50661301_38_dialog_content = "O Senhor Aqua me confiou a construção de um novo templo, mas depois de trabalharmos tanto para construí-lo... O Rei Tritão o capturou para si mesmo.",
  ui_story_5066_50661301_39_dialog_content = "Snif... É tudo culpa minha...",
  ui_story_5066_50661301_40_dialog_content = "Mantenha a esperança, Connolly. Viu? Os moradores já têm uma nova ideia!",
  ui_story_5066_50661301_41_dialog_content = "Hã...? Tudo bem então... Por favor, compartilhe seus pensamentos comigo!",
  ui_story_5066_50661301_42_dialog_content = "Acredito que o clarinete seja apenas um tipo de instrumento musical.",
  ui_story_5066_50661301_43_dialog_content = "Já que não tem clarinete, podemos usar outros instrumentos no lugar?",
  ui_story_5066_50661301_44_dialog_content = "Talvez o Senhor Aqua não seja tão exigente em relação ao timbre, sabe?",
  ui_story_5066_50661301_45_dialog_content = "Não... Exigente?",
  ui_story_5066_50661301_46_dialog_content = "Algo vem à mente?",
  ui_story_5066_50661301_47_dialog_content = "Mas... Todo esse tempo, eu acreditei que o poder residia no instrumento que minha mãe me deixou...",
  ui_story_5066_50661301_48_dialog_content = "É realmente possível se comunicar com o Senhor das Águas sem o clarinete dela...?",
  ui_story_5066_50661301_49_dialog_content = "Eu acredito que seja possível.",
  ui_story_5066_50661301_50_dialog_content = "Huh...?!",
  ui_story_5066_50661301_51_dialog_content = "Acho que a habilidade de se comunicar com o Aqua Lord pode ser um poder inato seu.",
  ui_story_5066_50661301_52_dialog_content = "Meu próprio poder...? Mas... Mas como isso pode ser...?",
  ui_story_5066_50661301_53_dialog_content = "Mas pense nisso: antes de fazer o pacto, você já não tinha a habilidade de se comunicar com o Aqua Lord através da música?",
  ui_story_5066_50661301_54_dialog_content = "Além disso, mesmo sem a clarineta, os tentáculos não desapareceram; eles apenas estão menos responsivos.",
  ui_story_5066_50661301_55_dialog_content = "Então, pode não ser apenas sobre o clarinete; o que realmente importa pode ser sua música, certo?",
  ui_story_5066_50661301_56_dialog_content = "Minha... música?",
  ui_story_5066_50661301_57_dialog_content = "Isso mesmo. Tente refletir sobre suas batalhas passadas.",
  ui_story_5066_50661301_58_dialog_content = "E pense sobre o que exatamente te deu essa força...",
  ui_story_5066_50661302_1_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50661302_2_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50661302_3_dialog_content = "...",
  ui_story_5066_50661302_4_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50661302_5_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50661302_6_dialog_content = "Eca...!",
  ui_story_5066_50661302_7_dialog_content = "...",
  ui_story_5066_50661302_8_dialog_content = "Eu... eu me lembro agora...",
  ui_story_5066_50661302_9_dialog_content = "Minha mãe uma vez disse que o poder da música não está nos instrumentos, mas na própria música...",
  ui_story_5066_50661302_10_dialog_content = "Eu estava tão ocupado valorizando o clarinete que ela me deixou que esqueci tudo sobre o que ela me ensinou...",
  ui_story_5066_50661302_11_dialog_content = "Mas você se lembrou agora, não é?",
  ui_story_5066_50661302_12_dialog_content = "Sim. Então agora... Se eu encontrar a música certa, talvez consiga invocar o Senhor das Águas novamente...",
  ui_story_5066_50661302_13_dialog_content = "Assim como... quando eu o invoquei pela primeira vez no sótão.",
  ui_story_5066_50661302_14_dialog_content = "Você ainda se lembra da partitura musical que tocou naquela época?",
  ui_story_5066_50661302_15_dialog_content = "Eu assisti... É chamado \"A Forma da Água\"...",
  ui_story_5066_50661302_16_dialog_content = "Mas...",
  ui_story_5066_50661302_17_dialog_content = "O quê, você não consegue mais tocar essa partitura?",
  ui_story_5066_50661302_18_dialog_content = "Sim... a partitura ainda está no sótão da minha tia...",
  ui_story_5066_50661302_19_dialog_content = "Mas agora... A cidade inteira está sob o controle do Rei Tritão.",
  ui_story_5066_50661302_20_dialog_content = "Toquei apenas algumas vezes, e essa música é realmente complexa...",
  ui_story_5066_50661302_21_dialog_content = "O que provavelmente significa... que não conseguirei invocar o Aqua Lord...",
  ui_story_5066_50661302_22_dialog_content = "Não se estresse demais. Ainda temos muitas opções.",
  ui_story_5066_50661302_23_dialog_content = "Você também pode pensar se há alguma composição que possa despertar o interesse do Senhor Aqua, talvez?",
  ui_story_5066_50661302_24_dialog_content = "Ah... Tem sim! É uma música chamada <color=#FFB400>Casa</color>!",
  ui_story_5066_50661302_25_dialog_content = "Lar?",
  ui_story_5066_50661302_26_dialog_content = "Sim! É uma música maravilhosa... Uma que minha mãe me ensinou.",
  ui_story_5066_50661302_27_dialog_content = "É também a música que eu toquei... Quando o Senhor Aqua e eu finalmente começamos a nos entender!",
  ui_story_5066_50661302_28_dialog_content = "Acho que é isso! Essa música tem que funcionar!",
  ui_story_5066_50661302_29_dialog_content = "Hum... acho que sim, mas...",
  ui_story_5066_50661302_30_dialog_content = "E-eu não posso fazer promessas, então... você poderia me acompanhar até o templo... e me ajudar a invocar o Senhor da Água?",
  ui_story_5066_50661302_31_dialog_content = "Fique tranquilo, estarei bem ao seu lado.",
  ui_story_5066_50661302_32_dialog_content = "Além disso, todos lá ainda estão esperando por você.",
  ui_story_5066_50661302_33_dialog_content = "Esperem por mim, pessoal...",
  ui_story_5066_50661302_34_dialog_content = "Isso é para todos vocês...",
  ui_story_5066_50661302_35_dialog_content = "Se eu não tiver meu clarinete, usarei outro instrumento. Se não conseguir tocar A Forma da Água, então encontrarei outra música para tocar. De qualquer forma... eu definitivamente...",
  ui_story_5066_50661302_36_dialog_content = "Com certeza vou me comunicar com o Aqua Lord novamente!",
  ui_story_5066_50661401_1_dialog_content = "Huff... Huff... Finalmente estamos chegando perto...",
  ui_story_5066_50661401_2_dialog_content = "Obrigado por ficar comigo todo esse tempo, Golfinho Branco... Se não fosse por você...",
  ui_story_5066_50661401_3_dialog_content = "Esses são todos os seus próprios poderes; minha parte é bastante insignificante.",
  ui_story_5066_50661401_4_dialog_content = "E o momento em que você precisa mostrar seus verdadeiros poderes ainda está por vir.",
  ui_story_5066_50661401_5_dialog_content = "Oh... M-Mas você sempre estará lá para me ajudar, certo?",
  ui_story_5066_50661401_6_dialog_content = "Claro, estarei com você em cada passo do caminho.",
  ui_story_5066_50661401_7_dialog_content = "Ei, vamos ver quem é essa garotinha desgrenhada?",
  ui_story_5066_50661401_8_dialog_content = "Hã...? Você não é...?",
  ui_story_5066_50661401_9_dialog_content = "Nossa, não é o Queen Connolly? Faz um tempo que não te vejo, e você já está todo bagunçado?",
  ui_story_5066_50661401_10_dialog_content = "Primo...?",
  ui_story_5066_50661401_11_dialog_content = "O que está fazendo aqui?",
  ui_story_5066_50661401_12_dialog_content = "Magnífico estreia, não é? Está com inveja, não está? Este foi um presente do próprio Rei Tritão!",
  ui_story_5066_50661401_13_dialog_content = "Afinal, eu fui o maior herói desta batalha; agora sou um grande destaque diante do Rei Tritão!",
  ui_story_5066_50661401_14_dialog_content = "E você, meu pobre e inútil primo... se ao menos tivesse me ouvido naquela época e se tornado o colecionável do Príncipe Tritão.",
  ui_story_5066_50661401_15_dialog_content = "Você nunca acabaria em uma situação tão miserável! Hahaha...",
  ui_story_5066_50661401_16_dialog_content = "Maior contribuidor...?",
  ui_story_5066_50661401_17_dialog_content = "(Mas... Meu primo nunca teve nenhum talento de verdade! Como ele poderia ser o \"maior colaborador\" na campanha do rei...?)",
  ui_story_5066_50661401_18_dialog_content = "(Poderia ser?!)",
  ui_story_5066_50661401_19_dialog_content = "Foi você... Você foi quem roubou meu clarinete, não foi?!",
  ui_story_5066_50661401_20_dialog_content = "Ah... Então você só percebeu isso agora? Não é um pouco tarde e bobo demais, minha querida prima?",
  ui_story_5066_50661401_21_dialog_content = "Mas mesmo que você tenha percebido, o que pode fazer agora?",
  ui_story_5066_50661401_22_dialog_content = "Você tem alguma maneira de se vingar de mim? Duvido!",
  ui_story_5066_50661401_23_dialog_content = "Por favor... Me devolva...",
  ui_story_5066_50661401_24_dialog_content = "O que você disse? Você...",
  ui_story_5066_50661401_25_dialog_content = "Eu disse por favor me devolva meu clarinete...!",
  ui_story_5066_50661401_26_dialog_content = "Apenas palavras vazias...",
  ui_story_5066_50661401_27_dialog_content = "Estou bem ciente de que, sem esse clarinete, você é absolutamente inútil!",
  ui_story_5066_50661401_28_dialog_content = "Eu...? É verdade que não há nada de especial em mim...",
  ui_story_5066_50661401_29_dialog_content = "Mas o verdadeiro poder... está na música!",
  ui_story_5066_50661401_30_dialog_content = "Poder... Que piada...",
  ui_story_5066_50661401_31_dialog_content = "Mesmo sem meu clarinete, eu posso usar minha voz...",
  ui_story_5066_50661401_32_dialog_content = "E mesmo sem minhas partituras... Suas melodias e emoções foram gravadas no meu coração há muito tempo.",
  ui_story_5066_50661401_33_dialog_content = "Agora, tudo que eu preciso fazer é cantar!",
  ui_story_5066_50661401_34_dialog_content = "*canta*",
  ui_story_5066_50661401_35_dialog_content = "<color=#e8d9bb>Como uma princesa retornando ao seu castelo, Connolly canta enquanto sobe as escadas sinuosas, usando sua voz para invocar o Senhor da Água...</color>",
  ui_story_5066_50661401_36_dialog_content = "<color=#e8d9bb>Ao mesmo tempo, ela finalmente expressa os sentimentos que manteve escondidos em seu coração por tanto tempo.</color>",
  ui_story_5066_50661401_37_dialog_content = "Cala a boca! Pare de cantar... Pare! Fique longe de mim!",
  ui_story_5066_50661401_38_dialog_content = "Apenas um lugar onde todos se reúnem pode ser chamado de lar!♪",
  ui_story_5066_50661401_39_dialog_content = "Um castelo vazio, não importa quão grandioso, sempre se sentirá sozinho!♪",
  ui_story_5066_50661401_40_dialog_content = "Então, por favor, ouça meu chamado e volte para o meu lado!♪",
  ui_story_5066_50661401_41_dialog_content = "Pois aqui é seu lar, onde você não precisa se esconder!♪",
  ui_story_5066_50661401_42_dialog_content = "<color=#e8d9bb>Enquanto sua voz ecoa, vários peixes e partículas de Lumina começam a se reunir em torno de Connolly, como se juntassem-se a ela em oração por um milagre...</color>",
  ui_story_5066_50661401_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_45_dialog_content = "...",
  ui_story_5066_50661401_46_dialog_content = "Senhor Aqua... Estou tão feliz em vê-lo novamente...",
  ui_story_5066_50661401_47_dialog_content = "...",
  ui_story_5066_50661401_48_dialog_content = "Sinto muito... Eu estraguei tudo...",
  ui_story_5066_50661401_49_dialog_content = "Você deve estar tão decepcionado... por ter feito um pacto com alguém tão vergonhoso e inútil quanto eu... certo?",
  ui_story_5066_50661401_50_dialog_content = "Talvez eu não tenha mais o direito de dizer que estamos ligados... E talvez seja descarado da minha parte perguntar... Mas vou fazer isso mesmo assim!",
  ui_story_5066_50661401_51_dialog_content = "Agora mesmo... Eu realmente, realmente preciso da sua ajuda!",
  ui_story_5066_50661401_52_dialog_content = "Então, por favor... me empreste seu poder mais uma vez?!",
  ui_story_5066_50661401_53_dialog_content = "...",
  ui_story_5066_50661401_54_dialog_content = "Eu não detesto sua atitude atual.",
  ui_story_5066_50661401_55_dialog_content = "Esses acidentes não são todos culpa sua.",
  ui_story_5066_50661401_56_dialog_content = "Pelo menos suas intenções chegaram até mim.",
  ui_story_5066_50661401_57_dialog_content = "Então isso significa...?!",
  ui_story_5066_50661401_58_dialog_content = "Mas agora... eu não posso te ajudar...",
  ui_story_5066_50661401_59_dialog_content = "Ah... Eu sabia... mas eu entendo...",
  ui_story_5066_50661401_60_dialog_content = "Não me entenda mal.",
  ui_story_5066_50661401_61_dialog_content = "O médium se perdeu e o pacto foi quebrado prematuramente. Perdi minha forma física neste mundo.",
  ui_story_5066_50661401_62_dialog_content = "Agora, se você deseja obter meu poder, deve ir ao templo...",
  ui_story_5066_50661401_63_dialog_content = "Bem, para ser preciso, você deve ir àquele castelo extravagante que você construiu para mim e extrair todo o poder restante.",
  ui_story_5066_50661401_64_dialog_content = "Mas...",
  ui_story_5066_50661401_65_dialog_content = "Hum... Tem algum tipo de pegadinha...?",
  ui_story_5066_50661401_66_dialog_content = "Mas se você quiser aproveitar ao máximo esse poder, precisará herdar o templo e se tornar o verdadeiro Aqua Queen.",
  ui_story_5066_50661401_67_dialog_content = "A verdadeira... Aqua Queen...?",
  ui_story_5066_50661401_68_dialog_content = "Você está dizendo... Que eu sou apenas um impostor agora?",
  ui_story_5066_50661401_69_dialog_content = "Você não é um impostor. A questão é que, se você só pretende se proteger, já chegou longe o suficiente.",
  ui_story_5066_50661401_70_dialog_content = "Minha presença residual é suficiente para abrigar você.",
  ui_story_5066_50661401_71_dialog_content = "No entanto, se você pretende proteger a cidade, minha presença residual é muito fraca em termos de poder.",
  ui_story_5066_50661401_72_dialog_content = "Você precisará abraçar mais poder e... assumir mais responsabilidades.",
  ui_story_5066_50661401_73_dialog_content = "Você deve avançar, das sombras para os holofotes, para a escuridão onde nem mesmo meu poder pode protegê-lo...",
  ui_story_5066_50661401_74_dialog_content = "Ehehehe...",
  ui_story_5066_50661401_75_dialog_content = "O quê? Você acha minhas palavras engraçadas?",
  ui_story_5066_50661401_76_dialog_content = "É só que, pela primeira vez... Você parece meio denso...",
  ui_story_5066_50661401_77_dialog_content = "Por que você diz isso...?",
  ui_story_5066_50661401_78_dialog_content = "Os meus sentimentos não ficaram perfeitamente claros na minha música agora? Além disso...",
  ui_story_5066_50661401_79_dialog_content = "Agora que o Golfinho Branco está me ajudando, junto com todos os outros...",
  ui_story_5066_50661401_80_dialog_content = "Claro que eu escolheria continuar.",
  ui_story_5066_50661401_81_dialog_content = "Parece que eu posso ter subestimado você desta vez...",
  ui_story_5066_50661401_82_dialog_content = "Então, mostre-me o poder da sua determinação.",
  ui_story_5066_50661401_83_dialog_content = "Eu vou... E prometo que não vou te decepcionar de novo...",
  ui_story_5066_50661401_84_dialog_content = "Agora, querido primo... Você pode me devolver meu clarinete, por favor?",
  ui_story_5066_50661401_85_dialog_content = "Ou... você prefere sentir toda a força da minha raiva pelo que fez...?",
  ui_story_5066_50661401_86_dialog_content = "Tsc...",
  ui_story_5066_50661401_87_dialog_content = "(O poder dela ainda não se recuperou totalmente. Contanto que eu possa detê-la aqui, ela continuará sendo uma garota comum!)",
  ui_story_5066_50661401_88_dialog_content = "Heh, vamos lá, primo...",
  ui_story_5066_50661401_89_dialog_content = "Servindo ao Rei Peixe, minha força aumentou muito mais do que você pode imaginar.",
  ui_story_5066_50661401_90_dialog_content = "E desta vez, vou com tudo, o tipo de tudo que vai acabar com sua vida miserável! Vamos lá!",
  ui_story_5066_50661402_1_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50661402_2_dialog_content = "*canta*",
  ui_story_5066_50661402_3_dialog_content = "Aghhh! Ai ai... Chega! Connolly, pare com isso. Eu sou seu primo!",
  ui_story_5066_50661402_4_dialog_content = "O clarinete, você diz? Tudo bem, eu... eu vou devolver para você...",
  ui_story_5066_50661402_5_dialog_content = "Por favor... por favor, não me mate! Eu te imploro...",
  ui_story_5066_50661402_6_dialog_content = "Você não faria algo tão cruel e injusto, faria? Sua tia e seu tio ficariam devastados, você sabe, devastados!",
  ui_story_5066_50661402_7_dialog_content = "Isso mesmo, eles ainda estão esperando você voltar para casa!",
  ui_story_5066_50661402_8_dialog_content = "Casa...",
  ui_story_5066_50661402_9_dialog_content = "Exatamente, lar, o nosso lar! Vamos, vamos para casa ficar com nossas famílias, aqueles que realmente nos amam!",
  ui_story_5066_50661402_10_dialog_content = "...",
  ui_story_5066_50661402_11_dialog_content = "Embora eu esteja grato à minha tia e ao meu tio por me acolherem depois de eu perder tudo...",
  ui_story_5066_50661402_12_dialog_content = "Aquele lugar não é mais minha casa...",
  ui_story_5066_50661402_13_dialog_content = "Além disso, você foi quem quis me tirar da casa deles... Não foi, primo?!",
  ui_story_5066_50661402_14_dialog_content = "E agora você quer destruir as casas dessas pessoas também... Não se engane, você é meu inimigo agora.",
  ui_story_5066_50661402_15_dialog_content = "Eek! Não... é só um grande mal-entendido, você... por favor, não me mate!!",
  ui_story_5066_50661402_16_dialog_content = "Eu... eu nunca mataria alguém... Você e eu não somos iguais...",
  ui_story_5066_50661402_17_dialog_content = "Então vá embora... saia desta cidade agora mesmo... E nunca mais volte!",
  ui_story_5066_50661402_18_dialog_content = "Tudo bem, eu entendo. Apenas me deixe ir; eu nunca mais voltarei e você nunca mais me verá...",
  ui_story_5066_50661402_19_dialog_content = "...",
  ui_story_5066_50661402_20_dialog_content = "Eu não deveria estar incomodando meu primo agora...",
  ui_story_5066_50661402_21_dialog_content = "O Rei Tritão já ocupou a maior parte desta área. E não só isso...",
  ui_story_5066_50661402_22_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661402_23_dialog_content = "O som do disparo de canhões está ficando mais próximo. Na verdade, parece que está vindo diretamente em minha direção...",
  ui_story_5066_50661402_24_dialog_content = "Mas estou pronto para isso desta vez!",
  ui_story_5066_50661402_25_dialog_content = "Dayna, Robyn, todos... Por favor, fiquem seguros!",
  ui_story_5066_50661501_1_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661501_2_dialog_content = "Argh! Não me diga que também temos que desistir desta posição?!",
  ui_story_5066_50661501_3_dialog_content = "Não há fim para todos esses malditos guardas Tritões!",
  ui_story_5066_50661501_4_dialog_content = "Dayna... Devemos recuar por enquanto...",
  ui_story_5066_50661501_5_dialog_content = "Mas se recuarmos agora, só colocaremos o Connolly em mais perigo!",
  ui_story_5066_50661501_6_dialog_content = "Você pode continuar, não pode Robyn?",
  ui_story_5066_50661501_7_dialog_content = "Se for pelo Connolly... Eu posso aguentar um pouco mais.",
  ui_story_5066_50661501_8_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50661501_9_dialog_content = "Eram... tentáculos?!",
  ui_story_5066_50661501_10_dialog_content = "É Connolly... ela voltou...",
  ui_story_5066_50661501_11_dialog_content = "Ah... D-desculpe por deixar todo mundo esperando...!",
  ui_story_5066_50661501_12_dialog_content = "\"Nos deixar esperando\"? Pare de ser tão educado conosco!",
  ui_story_5066_50661501_13_dialog_content = "Ver que você está bem... é a melhor notícia que poderíamos receber...",
  ui_story_5066_50661501_14_dialog_content = "Então, você recuperou seus poderes?",
  ui_story_5066_50661501_15_dialog_content = "Não, parece que... Ela ficou ainda mais forte...",
  ui_story_5066_50661501_16_dialog_content = "Perfeito! Então vamos dar uma lição nesses idiotas e fazê-los correr, Connolly!",
  ui_story_5066_50661501_17_dialog_content = "C-Certo! Vou dar tudo de mim!",
  ui_story_5066_50661501_18_dialog_content = "<color=#e8d9bb>Estrondo—Estalo—</color>",
  ui_story_5066_50661501_19_dialog_content = "<color=#e8d9bb>Uau, uau, uau—Tapa!</color>",
  ui_story_5066_50661501_20_dialog_content = "Ei, eu pensei que vocês fossem mais fortes do que isso!",
  ui_story_5066_50661501_21_dialog_content = "Nem um único de vocês consegue lutar?!",
  ui_story_5066_50661501_22_dialog_content = "<color=#e8d9bb>Estrondo—Estalo—</color>",
  ui_story_5066_50661501_23_dialog_content = "Connolly... A força que você tem agora... Estou tão aliviado...",
  ui_story_5066_50661501_24_dialog_content = "Sim... E é tudo porque vocês me deram tanto tempo. Muito, muito obrigado...",
  ui_story_5066_50661501_25_dialog_content = "Não precisa nos agradecer, especialmente quando ainda há muita luta pela frente!",
  ui_story_5066_50661501_26_dialog_content = "<color=#e8d9bb>Estrondo—Estalo—</color>",
  ui_story_5066_50661501_27_dialog_content = "...",
  ui_story_5066_50661501_28_dialog_content = "Chega de peixe pequeno! Tragam logo esse rei arrogante de vocês!",
  ui_story_5066_50661501_29_dialog_content = "Robyn, vá dar uma mão para Connolly.",
  ui_story_5066_50661501_30_dialog_content = "Rogério...",
  ui_story_5066_50661501_31_dialog_content = "Parece que esse é o verdadeiro poder do Aqua Queen.",
  ui_story_5066_50661501_32_dialog_content = "Interessante. Realmente é um pouco incrível.",
  ui_story_5066_50661501_33_dialog_content = "Mas vocês realmente acreditam que estou perdendo agora?",
  ui_story_5066_50661501_34_dialog_content = "Você... Seja lá o que estiver planejando, eu... eu não vou deixar você se safar!",
  ui_story_5066_50661501_35_dialog_content = "Hahahaha, me parar? Eu tenho todas as informações sobre você!",
  ui_story_5066_50661501_36_dialog_content = "Então, todo o poder do Senhor Aqua vem daquele lar que você construiu, daquele castelo, não é?",
  ui_story_5066_50661501_37_dialog_content = "Vou buscar mais bolas de canhão nas águas rasas e explodir o castelo completamente! Que o poder do Senhor Aqua se disperse totalmente!",
  ui_story_5066_50661501_38_dialog_content = "E você se chama de rei, lutando desse jeito? Você é desprezível, mas pelo menos tem a coragem de finalmente admitir isso!",
  ui_story_5066_50661501_39_dialog_content = "Heh, tem algum problema com isso? O que você pode fazer?",
  ui_story_5066_50661501_40_dialog_content = "Connolly, se você declarar sua lealdade a mim agora, eu posso deixar você e aquele monstro viverem.",
  ui_story_5066_50661501_41_dialog_content = "Faça sua escolha rápido; não quero perder mais tempo com você.",
  ui_story_5066_50661501_42_dialog_content = "Eu... Eu prometi ao Senhor Aqua que protegeria sua casa... E a casa de todos os outros também.",
  ui_story_5066_50661501_43_dialog_content = "Este é o meu dever... E eu não vou mais fugir dele!",
  ui_story_5066_50661501_44_dialog_content = "Se você realmente está disposto a explodir o templo...",
  ui_story_5066_50661501_45_dialog_content = "Então, pela minha autoridade como Aqua Queen... Para defender esta cidade, eu declaro guerra a você!",
  ui_story_5066_50661501_46_dialog_content = "Excelente, é hora de acabar com a farsa de vocês, rebeldes.",
  ui_story_5066_50661501_47_dialog_content = "Todas as unidades! Sob meu comando! Lancem um ataque em larga escala na cidade!",
  ui_story_5066_50661501_48_dialog_content = "Não poupe nenhum dos rebeldes na cidade!",
  ui_story_5066_50661501_49_dialog_content = "...",
  ui_story_5066_50661501_50_dialog_content = "...",
  ui_story_5066_50661501_51_dialog_content = "...",
  ui_story_5066_50661501_52_dialog_content = "<size=50>Ohhhhhh!</size>",
  ui_story_5066_50661601_1_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50661601_2_dialog_content = "<color=#e8d9bb>Bata—Bata!</color>",
  ui_story_5066_50661601_3_dialog_content = "Ugh...",
  ui_story_5066_50661601_4_dialog_content = "Ugh...",
  ui_story_5066_50661601_5_dialog_content = "...",
  ui_story_5066_50661601_6_dialog_content = "Parece que a informação daquele coringa estava errada...",
  ui_story_5066_50661601_7_dialog_content = "O poder vem da própria música, não desse clarinete!",
  ui_story_5066_50661601_8_dialog_content = "Mas assim, heh, as coisas ficaram muito fáceis!",
  ui_story_5066_50661601_9_dialog_content = "Ao meu comando!",
  ui_story_5066_50661601_10_dialog_content = "...!",
  ui_story_5066_50661601_11_dialog_content = "Faça o maior barulho possível para interferir na música do Aqua Queen!",
  ui_story_5066_50661601_12_dialog_content = "Sim!",
  ui_story_5066_50661601_13_dialog_content = "Arghhhh! Calem suas bocas estúpidas, todos vocês!",
  ui_story_5066_50661601_14_dialog_content = "Não podemos deixar esses idiotas continuarem fazendo todo esse barulho! Vamos, Robyn!",
  ui_story_5066_50661601_15_dialog_content = "Entendido... Temos que impedi-los...",
  ui_story_5066_50661601_16_dialog_content = "<color=#e8d9bb>Estrondo—Bam—</color>",
  ui_story_5066_50661601_17_dialog_content = "Mais alto, faça mais alto! Deixe ecoar!",
  ui_story_5066_50661601_18_dialog_content = "Urgh... Eles são tão barulhentos! Mal consigo ouvir minha própria voz...",
  ui_story_5066_50661601_19_dialog_content = "Neste ritmo... Não me diga que vai acontecer de novo...",
  ui_story_5066_50661601_20_dialog_content = "Não precisa ter medo, Connolly.",
  ui_story_5066_50661601_21_dialog_content = "O Golfinho Branco... Você veio me ajudar de novo?",
  ui_story_5066_50661601_22_dialog_content = "Eu... Eu sei que não deveria desanimar tão facilmente, mas... Como vou tocar minha música agora...?",
  ui_story_5066_50661601_23_dialog_content = "Seja você mesmo.",
  ui_story_5066_50661601_24_dialog_content = "Apenas... Ser eu mesmo...?",
  ui_story_5066_50661601_25_dialog_content = "Isso mesmo. Sua performance não é feita para batalhas, não é?",
  ui_story_5066_50661601_26_dialog_content = "Qual é o propósito da sua música?",
  ui_story_5066_50661601_27_dialog_content = "O significado da minha música...",
  ui_story_5066_50661601_28_dialog_content = "Ainda assim, eu não estou completamente infeliz...",
  ui_story_5066_50661601_29_dialog_content = "E isso é porque... Eu ainda tenho minha música! Ainda tenho o instrumento e as partituras que minha mãe me deixou...",
  ui_story_5066_50661601_30_dialog_content = "<color=#e8d9bb>Quando Connolly se sente solitária, ela toca aquelas melodias familiares.</color>",
  ui_story_5066_50661601_31_dialog_content = "<color=#e8d9bb>Uma marcha alegre em Lá Maior, uma balada lírica em Si Menor e uma sonata sombria em Dó Maior. Essas músicas não são apenas suas amigas, mas sua salvação.</color>",
  ui_story_5066_50661601_32_dialog_content = "E... Eu entendo agora.",
  ui_story_5066_50661601_33_dialog_content = "Eu sempre estava sozinho quando tocava minha música. Era minha maneira de me salvar...",
  ui_story_5066_50661601_34_dialog_content = "A alegria insubstituível de tocar música pertence a mim e a mais ninguém... É também o que eu faço de melhor...",
  ui_story_5066_50661601_35_dialog_content = "O que significa que eu ainda consigo fazer isso!",
  ui_story_5066_50661601_36_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50661601_37_dialog_content = "Barulho, cadê o barulho que você faz?! Você precisa ser mais alto do que aquela maldita música!",
  ui_story_5066_50661601_38_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50661601_39_dialog_content = "Uh-oh, o Rei Tritão tá com cara de bem salgado agora!",
  ui_story_5066_50661601_40_dialog_content = "Agora é a hora... De virar as marés da batalha...",
  ui_story_5066_50661701_1_dialog_content = "<color=#e8d9bb>Bang—Bang—</color>",
  ui_story_5066_50661701_2_dialog_content = "Vamos lá, bando de aberrações com cara de peixe! Me dê um desafio de verdade!",
  ui_story_5066_50661701_3_dialog_content = "Desde que Connolly voltou, a batalha ficou muito mais fácil... Que alívio...",
  ui_story_5066_50661701_4_dialog_content = "Esses guardas inúteis; não são confiáveis em momentos críticos...",
  ui_story_5066_50661701_5_dialog_content = "Mas vocês rebeldes, não fiquem tão convencidos tão cedo.",
  ui_story_5066_50661701_6_dialog_content = "Como rei, eu não pretendia lutar pessoalmente.",
  ui_story_5066_50661701_7_dialog_content = "Mas com coisas assim agora...",
  ui_story_5066_50661701_8_dialog_content = "...?!",
  ui_story_5066_50661701_9_dialog_content = "Sua Majestade, não precisa...",
  ui_story_5066_50661701_10_dialog_content = "Cale a boca! Diga a todos para cessarem seus ataques sem sentido e redirecionar todo o poder de fogo em direção ao castelo!",
  ui_story_5066_50661701_11_dialog_content = "Estou cuidando pessoalmente do bombardeio!",
  ui_story_5066_50661701_12_dialog_content = "Vamos varrer esta cidade do mapa hoje, começando por aquele castelo amaldiçoado!",
  ui_story_5066_50661701_13_dialog_content = "Mas assim, mesmo que vençamos esta batalha, não ganharemos nada...",
  ui_story_5066_50661701_14_dialog_content = "Calem a boca, bando inútil! Apenas façam o que eu digo!",
  ui_story_5066_50661701_15_dialog_content = "Sim!!!",
  ui_story_5066_50661701_16_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661701_17_dialog_content = "A explosão do canhão pareceu ainda mais poderosa do que antes!",
  ui_story_5066_50661701_18_dialog_content = "Ele... está tentando destruir a cidade inteira...?",
  ui_story_5066_50661701_19_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661701_20_dialog_content = "E parece que eles estão concentrando fogo no próprio templo!",
  ui_story_5066_50661701_21_dialog_content = "Neste ritmo... O templo será reduzido a escombros em pouco tempo...",
  ui_story_5066_50661701_22_dialog_content = "Não... Não posso deixá-lo destruir o templo!",
  ui_story_5066_50661701_23_dialog_content = "Isso é... A casa do Senhor Aqua... E todos trabalharam tão duro para construí-la!",
  ui_story_5066_50661701_24_dialog_content = "Não podemos... Não vamos deixar o Rei Tritão derrubar isso!",
  ui_story_5066_50661701_25_dialog_content = "<color=#e8d9bb>Uau—Uau—Uau—</color>",
  ui_story_5066_50661701_26_dialog_content = "<color=#e8d9bb>Com toda a sua força, Connolly bloqueia cada disparo de canhão com seus tentáculos.</color>",
  ui_story_5066_50661701_27_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661701_28_dialog_content = "Connolly!!!",
  ui_story_5066_50661701_29_dialog_content = "Você vai se machucar se continuar assim!",
  ui_story_5066_50661701_30_dialog_content = "Mas o templo... Eu não posso deixar isso...",
  ui_story_5066_50661701_31_dialog_content = "...",
  ui_story_5066_50661701_32_dialog_content = "Tudo bem, Connolly, está tudo certo.",
  ui_story_5066_50661701_33_dialog_content = "Huh... É você, Lorde Aqua...?",
  ui_story_5066_50661701_34_dialog_content = "Sua determinação e emoções estão todas claras para mim.",
  ui_story_5066_50661701_35_dialog_content = "Vou proteger a cidade. Então você pode ir com tudo contra o Rei Tritão.",
  ui_story_5066_50661701_36_dialog_content = "Mas...",
  ui_story_5066_50661701_37_dialog_content = "Não há \"mas\". Connolly, eu já te disse que ser uma verdadeira rainha vem com mais responsabilidades...",
  ui_story_5066_50661701_38_dialog_content = "Mas nosso pacto... E sua casa...",
  ui_story_5066_50661701_39_dialog_content = "Casa... Ahahahahahah...",
  ui_story_5066_50661701_40_dialog_content = "Dessa vez, é você quem não entende.",
  ui_story_5066_50661701_41_dialog_content = "Eu...?",
  ui_story_5066_50661701_42_dialog_content = "Você já me contou há muito tempo, através de suas músicas, o verdadeiro significado de lar. Você não se lembra?",
  ui_story_5066_50661701_43_dialog_content = "A cidade é o lar de todos os moradores submarinos, e foram os habitantes da cidade e você juntos que construíram para mim um novo lar...",
  ui_story_5066_50661701_44_dialog_content = "Enquanto a cidade permanecer, a casa que desejo sempre poderá ser reconstruída, cedo ou tarde.",
  ui_story_5066_50661701_45_dialog_content = "Senhor Aqua...",
  ui_story_5066_50661701_46_dialog_content = "Vá agora. Desta vez, deixe-me juntar a você... para proteger nossa amada cidade, nosso lar mais precioso!",
  ui_story_5066_50661702_1_dialog_content = "<color=#e8d9bb>Vuuush—Tapa—</color>",
  ui_story_5066_50661702_2_dialog_content = "Ah...",
  ui_story_5066_50661702_3_dialog_content = "<color=#e8d9bb>Vuuush—Tapa—</color>",
  ui_story_5066_50661702_4_dialog_content = "Haa... Haa... Finalmente acabou...",
  ui_story_5066_50661702_5_dialog_content = "Droga…",
  ui_story_5066_50661702_6_dialog_content = "Eu... o poderoso Rei Tritão... não acredito que... perdi para alguém como você...",
  ui_story_5066_50661702_7_dialog_content = "Heheheheh... Não, eu ainda não perdi! Isso não acabou!",
  ui_story_5066_50661702_8_dialog_content = "Connolly, escute!",
  ui_story_5066_50661702_9_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661702_10_dialog_content = "O bombardeio ainda não acabou, mas você não tem mais o poder de impedi-lo!",
  ui_story_5066_50661702_11_dialog_content = "A vitória será minha! MINHA!",
  ui_story_5066_50661702_12_dialog_content = "Hahahaha... Viva o Reino dos Tritões!",
  ui_story_5066_50661702_13_dialog_content = "A cidade... todo mundo...",
  ui_story_5066_50661702_14_dialog_content = "Eu... eu posso estar completamente exausto agora, mas... não estou sozinho nesta luta!",
  ui_story_5066_50661702_15_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5066_50661702_16_dialog_content = "Aaahhhh—",
  ui_story_5066_50661702_17_dialog_content = "Não importa o quão alto seja o seu discurso, ele não vai abafar o som dos canhões!",
  ui_story_5066_50661702_18_dialog_content = "Sou o vencedor! É minha vitória!",
  ui_story_5066_50661702_19_dialog_content = "<color=#e8d9bb>Sob uma saraivada de tiros de canhão, o corpo de Connolly balança impotente como uma alga marinha.</color>",
  ui_story_5066_50661702_20_dialog_content = "<color=#e8d9bb>Olhando para cima, ela vê algo flutuando longe na superfície da água. Um brilho quente e familiar...</color>",
  ui_story_5066_50661702_21_dialog_content = "Senhor Aqua...",
  ui_story_5066_50661702_22_dialog_content = "Eu... Eu derrotei o Rei Tritão, como eu disse que faria... Eu cumpri minhas obrigações!",
  ui_story_5066_50661702_23_dialog_content = "Mas o seu corpo... O que aconteceu com ele?!",
  ui_story_5066_50661702_24_dialog_content = "Você se saiu bem...",
  ui_story_5066_50661702_25_dialog_content = "Mas para proteger a cidade... você precisará de um poder ainda mais avançado, o poder do verdadeiro Aqua Queen...",
  ui_story_5066_50661702_26_dialog_content = "Agora... passo esse poder para você.",
  ui_story_5066_50661702_27_dialog_content = "Não... Espere, Senhor Aqua! Isso não é o que combinamos...!",
  ui_story_5066_50661702_28_dialog_content = "Não deveríamos... Não deveríamos defender essa cidade juntos?!",
  ui_story_5066_50661702_29_dialog_content = "De fato, você... herdará todo o meu poder...",
  ui_story_5066_50661702_30_dialog_content = "E eu estarei com você sempre, protegendo a cidade...",
  ui_story_5066_50661702_31_dialog_content = "Protegendo... nosso lar.",
  ui_story_5066_50661702_32_dialog_content = "Espere, Aqua Lord... por favor, não desapareça... não me deixe sozinho...",
  ui_story_5066_50661702_33_dialog_content = "Para sempre, você... não estará sozinho...",
  ui_story_5066_50661702_34_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5066_50661702_35_dialog_content = "Aqua... Senhor...",
  ui_story_5066_50661702_36_dialog_content = "Esse poder... me sinto tão quente...",
  ui_story_5066_50661702_37_dialog_content = "Isso é... O poder total do Senhor Aqua... que ele passou para mim...",
  ui_story_5066_50661702_38_dialog_content = "Mas agora não é hora de lamentar...!",
  ui_story_5066_50661702_39_dialog_content = "A vontade e os desejos do Senhor Aqua... Agora são meus!",
  ui_story_5066_50661702_40_dialog_content = "Hunf... nada além de blefes!",
  ui_story_5066_50661702_41_dialog_content = "A verdade é que aquele monstro não resistiu ao meu bombardeio... e desapareceu. Não é óbvio?",
  ui_story_5066_50661702_42_dialog_content = "O canhão não vai parar de atirar, e você...",
  ui_story_5066_50661702_43_dialog_content = "<color=#e8d9bb>Connolly não fala, mas levanta suavemente seu clarinete.</color>",
  ui_story_5066_50661702_44_dialog_content = "Você... já chegou a esse ponto, o que mais pode fazer?!",
  ui_story_5066_50661702_45_dialog_content = "Esta canção de ninar é dedicada a você, assim como ao resto de seus soldados violentos e sem coração.",
  ui_story_5066_50661702_46_dialog_content = "Seu sonho de destruir esta cidade acabou. Agora é hora... de eu te enviar para um novo sonho.",
  ui_story_5066_50661702_47_dialog_content = "Por favor, aproveite enquanto te enviamos de volta ao Raso!",
  ui_story_5066_50661702_48_dialog_content = "*Toca uma melodia*",
  ui_story_5066_50661702_49_dialog_content = "<color=#e8d9bb>Connolly toca uma música delicada e emocionante, repleta do poder da amizade, lembranças e sua determinação inabalável.</color>",
  ui_story_5066_50661702_50_dialog_content = "<color=#e8d9bb>Todos os inimigos, incluindo o Rei Tritão, caem em um sono profundo enquanto Connolly realiza uma performance perfeita...</color>",
  ui_story_5066_50661702_51_dialog_content = "Não acredito. Bastou uma única música para transformar aqueles sereianos sanguinários em um cardume de peixes sonolentos!",
  ui_story_5066_50661702_52_dialog_content = "Levante-se, bafo de isca! Ainda não terminamos de lutar!",
  ui_story_5066_50661702_53_dialog_content = "Então este é o poder de Connolly... Mas parece que algo ruim também aconteceu...",
  ui_story_5066_50661702_54_dialog_content = "Sim, eu sei.",
  ui_story_5066_50661702_55_dialog_content = "O Lorde Aqua se foi agora, certo?",
  ui_story_5066_50661702_56_dialog_content = "É por isso que devemos estar confortando-a agora, em vez de ficarmos parados aqui...",
  ui_story_5066_50661702_57_dialog_content = "Entendi! Vamos embora!",
  ui_story_5066_50661702_58_dialog_content = "É... É realmente o fim desta vez?",
  ui_story_5066_50661702_59_dialog_content = "Você fez um trabalho fantástico, Connolly.",
  ui_story_5066_50661702_60_dialog_content = "P-Por favor, não me elogie. Eu deveria estar te agradecendo por me guiar todo esse tempo...",
  ui_story_5066_50661702_61_dialog_content = "Apenas uma pequena ajuda minha. Devo dizer, sua aparência enquanto cantava aquela canção de ninar agora há pouco estava ao mesmo tempo elegante e graciosa.",
  ui_story_5066_50661702_62_dialog_content = "Aaahhhh... V-Você está tirando sarro de mim, não é?!",
  ui_story_5066_50661702_63_dialog_content = "Ok, seus amigos estão chegando na hora certa; vamos todos comemorar essa vitória juntos!",
  ui_story_5066_50661702_64_dialog_content = "Ei, Connolly! Aqui!",
  ui_story_5066_50661702_65_dialog_content = "Olha, nós reunimos todos os tritões dormindo em um só lugar!",
  ui_story_5066_50661702_66_dialog_content = "Eles são realmente viscosos... Foi muito mais trabalho do que eu pensava...",
  ui_story_5066_50661702_67_dialog_content = "O Rei Tritão tem uma cabeça bem grande, né? Será que conseguimos encaixá-lo lá?",
  ui_story_5066_50661702_68_dialog_content = "Acho que... Ele vai se encaixar perfeitamente!",
  ui_story_5066_50661702_69_dialog_content = "Tudo bem, aqui vai!",
  ui_story_5066_50661702_70_dialog_content = "Atacar uma cidade indefesa com canhões e explosivos... Aposto que nem mesmo um tirano como ele pensou nisso...",
  ui_story_5066_50661702_71_dialog_content = "Que ele também seria lançado de um canhão algum dia, hein?",
  ui_story_5066_50661702_72_dialog_content = "Sinceramente, estou animado para ver como vai ser...",
  ui_story_5066_50661702_73_dialog_content = "Eu... Eu só acho que essa é a melhor maneira de tirar todos eles daqui...",
  ui_story_5066_50661702_74_dialog_content = "Esta pequena cidade finalmente conhecerá paz e segurança depois disso...",
  ui_story_5066_50661702_75_dialog_content = "Você pode acender o pavio já, Connolly? Estou louco para ver essa coisa explodir!",
  ui_story_5066_50661702_76_dialog_content = "Ok, claro...",
  ui_story_5066_50661702_77_dialog_content = "Três, dois, um—Fogo!",
  ui_story_5066_50661702_78_dialog_content = "<size=45><color=#e8d9bb>Estrondo—!</color></size>",
  ui_story_5066_50661702_79_dialog_content = "Hum... É assim que tudo deve terminar, Golfinho Branco...?",
  ui_story_5066_50661702_80_dialog_content = "Claro. Não há final melhor do que este.",
  ui_story_5066_50661702_81_dialog_content = "Para todos vocês, tritões feios, espero que aproveitem este sonho dentro de um sonho.",
  ui_story_5066_50661801_1_dialog_content = "Ufa... Finalmente tudo acabou...",
  ui_story_5066_50661801_2_dialog_content = "Tudo isso pareceu um sonho bizarro...",
  ui_story_5066_50661801_3_dialog_content = "Talvez... Se eu conseguisse adormecer como os outros peixes...",
  ui_story_5066_50661801_4_dialog_content = "Será que eu... Conseguiria ver o Senhor Aqua mais uma vez?",
  ui_story_5066_50661801_5_dialog_content = "Ei Connolly, essas pessoas dizem que suas casas foram destruídas na batalha. Não deveríamos encontrar uma maneira de abrigá-las por enquanto?",
  ui_story_5066_50661801_6_dialog_content = "E essa criança diz que se separou de sua mãe... Mas não se preocupe, vou ajudá-lo a procurar...",
  ui_story_5066_50661801_7_dialog_content = "Ahh, desculpe por isso...",
  ui_story_5066_50661801_8_dialog_content = "Agora não é hora de me afundar na minha tristeza...",
  ui_story_5066_50661801_9_dialog_content = "Prometi que me tornaria um verdadeiro Aqua Queen... E me recuso a fugir das minhas responsabilidades novamente...",
  ui_story_5066_50661801_10_dialog_content = "Dayna! Robyn! Estarei aí em breve...",
  ui_story_5066_50661801_11_dialog_content = "<color=#e8d9bb>Swish—Swish—Swish—</color>",
  ui_story_5066_50661801_12_dialog_content = "Hã?!",
  ui_story_5066_50661801_13_dialog_content = "São... tentáculos de água? Mas eles são tão pequenos...",
  ui_story_5066_50661801_14_dialog_content = "Senhor Aqua... Você ainda está aqui?! Você nunca me deixou, não é...?",
  ui_story_5066_50661801_15_dialog_content = "Senhor Aqua? Mas... você não é o verdadeiro Senhor Aqua?!",
  ui_story_5066_50661801_16_dialog_content = "Hã...? M-Eu?!",
  ui_story_5066_50661801_17_dialog_content = "Isso mesmo, somos seus servos... e seus amigos...",
  ui_story_5066_50661801_18_dialog_content = "Viemos ficar com você para que não se sinta sozinho!",
  ui_story_5066_50661801_19_dialog_content = "Faz companhia pra mim...?",
  ui_story_5066_50661801_20_dialog_content = "De fato, você... herdará todo o meu poder...",
  ui_story_5066_50661801_21_dialog_content = "E eu estarei com você sempre, protegendo a cidade...",
  ui_story_5066_50661801_22_dialog_content = "Protegendo... nosso lar.",
  ui_story_5066_50661801_23_dialog_content = "Para sempre, você... não estará sozinho...",
  ui_story_5066_50661801_24_dialog_content = "(Então isso significa... O Senhor da Água não desapareceu completamente...)",
  ui_story_5066_50661801_25_dialog_content = "(Em vez disso, voltou... Como três entidades diferentes!)",
  ui_story_5066_50661801_26_dialog_content = "Uh... De onde exatamente... Vocês três vieram...?",
  ui_story_5066_50661801_27_dialog_content = "Viemos de outra dimensão!",
  ui_story_5066_50661801_28_dialog_content = "A dimensão da ilusão!",
  ui_story_5066_50661801_29_dialog_content = "A dimensão da imaginação!",
  ui_story_5066_50661801_30_dialog_content = "A dimensão da música!",
  ui_story_5066_50661801_31_dialog_content = "E tem... Três de vocês?",
  ui_story_5066_50661801_32_dialog_content = "Quando você fala, parece uma marcha, uma balada e uma sonata tocando tudo de uma vez.",
  ui_story_5066_50661801_33_dialog_content = "Desculpe, estou tendo um pouco de dificuldade para distinguir os três...",
  ui_story_5066_50661801_34_dialog_content = "Estou tocando marchas! O tom mais poderoso!",
  ui_story_5066_50661801_35_dialog_content = "Estou tocando baladas, as suaves melodias em tom menor.",
  ui_story_5066_50661801_36_dialog_content = "Estou tocando sonata, simples e profunda, na tonalidade maior mais profunda e ampla.",
  ui_story_5066_50661801_37_dialog_content = "Ó poderosa Aqua Queen, você consegue nos diferenciar agora?",
  ui_story_5066_50661801_38_dialog_content = "Agora consigo distinguir vocês perfeitamente! Cada um de vocês tem vozes tão lindas também!",
  ui_story_5066_50661801_39_dialog_content = "Mas ainda assim, por que você renasceu como três seres diferentes...?",
  ui_story_5066_50661801_40_dialog_content = "É constrangedor para o nobre Aqua Lord admitir, mas ele tem apenas um assistente! Ter três aumenta a majestade!",
  ui_story_5066_50661801_41_dialog_content = "Com apenas um amigo, você pode se sentir solitário às vezes, mas com três, isso não acontecerá.",
  ui_story_5066_50661801_42_dialog_content = "Ter um companheiro não é suficiente para uma família sólida, mas três são o suficiente para enfrentar as dificuldades.",
  ui_story_5066_50661801_43_dialog_content = "Connolly! A partir de hoje, deixe-nos ser aqueles que farão companhia a você!"
}
return config
